/* 江湖一生 · society, law, government, war and disaster: from a crooked tax runner at the door to floods, risings and sieges
   that sweep a whole region. Some of these run for years, and which side you took (the law, the people, the rebels) comes back later. */
'use strict';
const SOW=['wander','town'];
const soWd=s=>s.world||{h:0,u:0,p:1};
const soRg=s=>region(s)||{en:'the province',cn:'本地'};
const soAfter=(k,n)=>s=>s.flags[k]!=null&&s.age-s.flags[k]>=(n||1);

QHINT.so_lackey=T('You became the magistrate’s muscle. He has enemies at court.','你给县太爷当了打手。他在朝中也有对头。');
QHINT.so_sealhid=T('A lost imperial seal lies buried where only you know.','一方遗失的御印，埋在只有你知道的地方。');
QHINT.so_flood_q=T('You crossed the relief clerk after the flood. The county has not forgotten.','大水之后你得罪了放赈的书办。县里没忘这件事。');
QHINT.so_rebel=T('The peasant army you lead is still gathering.','你领头的义军还在聚拢人马。');
QHINT.so_rebel2=T('Your rising holds a county. The court will answer.','义军占了一县之地，朝廷迟早要回应。');
QHINT.so_loyal=T('You sided with the yamen against the rising. It is not over.','你站在了官府一边，这场民变还没完。');
QHINT.so_army=T('You enlisted for the frontier war. The army will march soon.','你投军去了边关，大军不日开拔。');
QHINT.so_army2=T('The frontier war is ending, but the army has not finished with you.','边关的仗快打完了，军中的事却还没完。');
QHINT.so_ledger=T('A dead man’s ledger against the Inner Watch is hidden in your things.','死者托付的那本揭发内缉司的账册，还藏在你身边。');
QHINT.so_ledger2=T('The ledger must reach the Censorate in the capital.','那本账册得送到京城都察院。');

/* =========================== small brushes with officialdom =========================== */
I({id:'so_taxman',age:[16,80],cd:8,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{sex:'m',age:rint(35,55)});return c},
 text:c=>T(`A tax runner, ${c.npc.en}, goes door to door with a ledger. Your household, he says, still owes “road money”, “bridge money”, and a small “tea fee” for his trouble. Nobody has ever heard of these taxes.`,`收税的差役${c.npc.zh}拿着账本挨家挨户敲门，说你家还欠着“修路钱”“修桥钱”，外加一份孝敬他的“茶钱”。这几样税，谁也没听说过。`),
 opts:[{l:T('Pay and be done with it','给钱了事'),cost:20,out:[{w:2,t:T('He moves on to the next door. Next season the tea fee doubles.','他转身去敲下一家的门。下一季，茶钱翻了一倍。'),c:'muted',fx:{happy:-2}},
   {w:s=>s.t.luck*.2,t:T('Next spring he squeezes the wrong family, a retired judge’s, and is sent off to guard a salt marsh. Your twenty taels are gone, but so is he.','第二年开春，他敲到了一位告老推官的家门上，被发配去看盐滩。你那二十两是没了，他也没了。'),c:'good',fx:{happy:3}}]},
  {l:T('Ask to see the tax edict','请他拿出公文来'),out:[{w:s=>s.smarts/25,t:T('You recite the real tax schedule back to him, line by line. He snaps the ledger shut and remembers urgent business elsewhere. Neighbours stop you in the lane to say thanks.','你把朝廷定的税目一条一条背给他听。他啪地合上账本，想起别处还有急事。街坊们在巷口拦住你道谢。'),c:'good',fx:{fame:1,align:2,happy:3}},
   {w:1.5,t:T('He writes your name in the ledger with a little flourish. Next year your household is assessed at twice the rate.','他在账本上写下你的名字，还特意描了一笔。第二年你家的税额翻了一倍。'),c:'bad',fx:{money:-30,happy:-3}}]},
  {l:T('Lean on him','吓唬吓唬他'),if:s=>power(s)>=15,out:[{w:s=>power(s)/40,t:T('You walk him to the edge of the village by the collar. The made-up taxes stop.','你揪着他的衣领，一路把他送到村口。那些名目从此没再提过。'),c:'good',fx:{align:2,fame:1}},
   {w:1.2,t:T('He comes back with two constables and a charge of assaulting an officer of the crown. It costs you a fine and a bad name at the yamen.','他带着两个捕快回来，告你殴打公差。你交了罚银，在衙门里也挂上了号。'),c:'bad',fx:{wanted:1,money:-20}}]}]});

I({id:'so_smuggle',age:[16,70],cd:10,tags:['wander'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:17,age:rint(30,50)});return c},
 text:c=>T(`At a mountain checkpoint, the guards are searching every merchant’s cart to the bottom. A friendly peddler, ${c.npc.en}, offers you forty taels to carry a small sealed box through. “They never search people on foot.”`,`山口的关卡上，兵丁把每辆商车都翻了个底朝天。一个和气的货郎${c.npc.zh}凑过来，说给你四十两，替${c.npc.ta}把一只封好的小木匣带过关。“走路的人，他们从来不搜。”`),
 opts:[{l:T('Carry the box','替他带过去'),out:[{w:s=>s.t.luck*.25+s.smarts/50,t:T('The guard glances at you and waves you through. On the far side the peddler counts out forty taels and will not say what was in the box.','兵丁瞟了你一眼，挥手放行。过了关，货郎数给你四十两银子，匣子里装的什么，一个字也不肯说。'),c:'muted',fx:{money:40,align:-2}},
   {w:1,t:T('A guard with a sharp nose opens the box: untaxed official salt. The peddler has vanished. Your purse buys your way out.','有个鼻子尖的兵丁打开了匣子：一匣私盐。货郎早没影了。你掏空了钱袋才脱身。'),c:'bad',fx:{f:s=>pay(s,-Math.min(s.money,rint(40,80)))}},
   {w:.35,t:T('The box holds salt, and the captain needs someone to blame. You get a year.','匣子里是私盐，关上的把总正缺个顶罪的。你被判了一年。'),c:'bad',fx:{jail:1,align:-2}}]},
  {l:T('Refuse','不干'),out:[{w:2,t:T('He shrugs and finds someone less careful.','他耸耸肩，另找了个不那么谨慎的人。'),c:'muted'},
   {w:s=>s.smarts/40,t:T('You watch him give the box to a farm boy. The boy is stopped; the peddler is already slipping away. You tell the guards which way he went, and they let the boy go.','你看着他把匣子塞给一个乡下少年。少年被拦下了，货郎正往外溜。你给兵丁指了他走的方向，少年被放了。'),c:'good',fx:{align:3,fame:1}}]},
  {l:T('Tell the guards','告诉兵丁'),out:[{w:s=>1+s.fame/20,t:T('They seize the peddler and a cart full of salt. The captain gives you twenty taels from the fine.','兵丁当场拿下货郎，还搜出一车私盐。把总从罚银里分了你二十两。'),c:'good',fx:{money:20,align:2}},
   {w:1,t:c=>T(`The captain thanks you, keeps the salt for himself, and lets ${c.npc.en} go. The peddler’s friends will remember your face.`,`把总谢过你，把盐收进了自己的库房，又把${c.npc.zh}放了。货郎的同伙会记住你这张脸。`),c:'bad',fx:{enemy:1,align:1}}]}]});

I({id:'so_pressgang',age:[16,65],cd:10,tags:SOW,ctx:s=>{const c=scene();c.npc=npc(s,{sex:'m',age:rint(15,17)});return c},
 text:c=>T(`Soldiers sweep through the market with a rope, tying young men together for the frontier army. One of them is ${c.npc.en}, a widow’s only son, barely old enough to shave. His mother is on her knees in the mud.`,`一队官兵拿着绳子扫过集市，见了青壮就往一串上拴，要押去边关充军。其中一个是${c.npc.zh}，寡妇家的独苗，嘴上刚长出绒毛。他娘跪在泥地里磕头。`),
 opts:[{l:T('Cut him loose','把人抢下来'),fight:FG(PW(.95,3),'injury',T('Press-gang in the market','集市抓丁'),T('the press-gang','抓丁的官兵'),()=>T('the press-gang','抓丁的官兵')),
   win:[{w:2,t:T('They drop the rope and run. Half the market goes home with them gone. The sergeant will be writing a report about you.','官兵丢下绳子跑了，集市上被拴的人一哄而散。那个什长回去少不了要告你一状。'),c:'good',fx:{align:4,fame:2,wanted:1}},
    {w:s=>s.fame/30,t:T('The sergeant recognises you, decides his quota can wait, and marches off empty-handed.','什长认出了你，琢磨了一下，觉得名额晚几天也无妨，空着手走了。'),c:'good',fx:{align:4,fame:3}}],
   lose:[{t:T('They beat you into the mud and take the boy anyway.','他们把你打翻在泥里，照样把少年拴走了。'),c:'bad',fx:{hurt:[6,14],cause:T('a press-gang','抓丁的官兵'),align:2}}]},
  {l:T('Bribe the sergeant','塞钱给什长'),cost:30,out:[{w:s=>1+s.t.luck*.2,t:T('Thirty taels buys the boy’s name off the list. His mother tries to give you a hen.','三十两银子，把少年的名字从册子上勾掉了。他娘非要塞给你一只母鸡。'),c:'good',fx:{align:3,happy:2}},
   {w:1,t:T('The sergeant takes the silver, and the boy. “Price went up,” he says.','什长收了银子，人照样带走。“价钱涨了。”他说。'),c:'bad',fx:{align:1,happy:-4}}]},
  {l:T('Argue the law: only sons are exempt','据理力争：独子免役'),out:[{w:s=>s.smarts/30+s.fame/40,t:T('You cite the statute so loudly the whole market hears it. The sergeant unties the boy to stop the noise.','你把律条喊得整个集市都听得见。什长嫌吵，解开了少年的绳子。'),c:'good',fx:{align:2,smarts:1}},
   {w:1.5,t:T('“I have a quota, not a law book,” says the sergeant, and tightens the rope.','“老子有的是名额，没有律书。”什长说着，把绳子又紧了紧。'),c:'bad',fx:{happy:-2}}]},
  {l:T('Look away','别过脸去'),out:[{w:1,t:T('The column marches out of town. You buy what you came for.','队伍出了城。你买了要买的东西。'),c:'muted',fx:{align:-2}},
   {w:s=>s.t.heart*.2,t:T('His mother’s voice follows you through every street of the market.','他娘的哭声，跟着你走遍了集市的每一条街。'),c:'bad',fx:{align:-1,happy:-3}}]}]});

I({id:'so_bridge',age:[14,75],cd:12,tags:['wander'],
 text:()=>T('A wedding procession is crossing the old stone bridge ahead of you when the middle span gives way. Drums, sedan chair and guests go into the brown river together.','前头一支迎亲队伍正走过老石桥，桥中间一段突然塌了。锣鼓、花轿连同宾客，一起掉进了浑黄的河水里。'),
 opts:[{l:T('Dive in','跳下去救人'),out:[{w:s=>power(s)/40+s.t.root*.1,t:T('You pull out the bride, still in her red veil, then two drummers. The groom’s family sends you a whole roast pig.','你先把还蒙着红盖头的新娘拖上岸，又捞起两个吹鼓手。新郎家抬来一整头烤猪谢你。'),c:'good',fx:{fame:3,align:4}},
   {w:1,t:T('You get one child to the bank before the current takes your strength. You are dragged out half-drowned, coughing river mud for a week.','你只把一个孩子推上了岸，水流就把你的力气卷走了。被人拖上来时你半死不活，咳了一个星期的泥水。'),c:'bad',fx:{hurt:[5,12],cause:T('a flooded river','湍急的河水'),align:3,ill:'cold'}}]},
  {l:T('Organise a human chain','招呼人手拉成人链'),out:[{w:s=>s.smarts/25+s.fame/40,t:T('Porters, fishermen and a butcher link arms at your shout. Everyone comes out alive. Later the county admits the bridge money was spent on the magistrate’s garden.','脚夫、渔民、屠户听了你的招呼，手挽着手下了水。一个都没少。后来县里才承认，修桥的银子修了县太爷的花园。'),c:'good',fx:{fame:2,align:3,smarts:1}},
   {w:1,t:T('Half the crowd argues over who goes first. You save two; the river keeps a flute player.','岸上的人吵着谁先下水。你救上来两个，河水留下了一个吹笛子的。'),c:'bad',fx:{align:2,happy:-3}}]},
  {l:T('Shout for help and stay dry','喊人帮忙，自己不下水'),out:[{w:1,t:T('Someone else goes in. People notice that you did not.','别人下了水。大家都看见你没下。'),c:'muted',fx:{fame:-1,align:-1}},
   {w:s=>s.t.luck*.15,t:T('A fishing boat comes round the bend just in time, and nets them all like carp.','一条渔船正好拐过河湾，像捞鲤鱼一样把人全捞了上来。'),c:'muted',fx:{happy:1}}]}]});

I({id:'so_gouger',age:[16,80],cd:8,tags:['town'],w:s=>soWd(s).h<=-1?2.5:0,when:s=>soWd(s).h<=-1,ctx:s=>{const c=scene();c.npc=npc(s,{occ:5,age:rint(40,60)});c.lv=PW(.9,2)(s);return c},
 text:c=>T(`The harvest has failed. The grain dealer ${c.npc.en} has locked his granary and sells rice by the cup at three times last year’s price, while families queue outside with empty sacks.`,`年景不好。粮商${c.npc.zh}锁了粮仓，米论碗卖，价钱是去年的三倍。门外排着长队，人人拎着空口袋。`),
 opts:[{l:T('Break open the granary','砸开粮仓'),fight:FG((s,c)=>c.lv,'injury',T('The locked granary','开仓放粮'),T('the granary guards','粮仓护院'),()=>T('the granary guards','粮仓护院')),
   win:[{w:2,t:T('You hand out grain by the basket until dark. The dealer files a complaint, but no constable in this county will serve it.','你一筐一筐地分粮，一直分到天黑。粮商递了状子，可这一县的捕快，没一个肯去拿你。'),c:'good',fx:{align:6,fame:3}},
    {w:1,t:T('The grain feeds the street for a month. The dealer’s brother-in-law at the yamen makes sure your name goes on a notice.','这些粮够一条街吃一个月。粮商在衙门里的小舅子，把你的名字写上了告示。'),c:'muted',fx:{align:6,fame:2,wanted:1}}],
   lose:[{t:T('His guards are well fed, and you are not. They throw you out into the queue.','护院吃得饱，你没吃饱。他们把你扔回了排队的人堆里。'),c:'bad',fx:{hurt:[5,12],cause:T('granary guards','粮仓护院')}}]},
  {l:T('Shame him in public','当众揭他的底'),out:[{w:s=>s.fame/25+s.smarts/50,t:T('You stand on a cart and read out his warehouse figures. The crowd grows; by noon he opens the granary at a fair price, to save his windows.','你站在车上，把他仓里存了多少粮一笔一笔念出来。人越聚越多。不到晌午，他为了保住门窗，按平价开了仓。'),c:'good',fx:{align:3,fame:2}},
   {w:1.5,t:T('He pays a storyteller to spread a tale that you hoard grain yourself. Some believe it.','他花钱雇了个说书的，说你自己才是囤粮的。有人信了。'),c:'bad',fx:{fame:-1,happy:-2}}]},
  {l:T('Buy grain and resell it','买粮转手'),if:s=>s.money>=50,out:[{w:s=>s.smarts/30+s.t.luck*.1,t:T('You buy in the next county and sell here. You make a good profit, and stop meeting people’s eyes.','你从邻县买粮，拿到这里卖。赚了一笔，却不太敢看人家的眼睛了。'),c:'muted',fx:{money:[40,120],align:-5}},
   {w:1,t:T('Relief grain arrives the week you buy. You eat your mistake, one bowl at a time.','你刚囤下粮，官府的赈粮就到了。这笔亏，你只能一碗一碗地吃下去。'),c:'bad',fx:{money:-40,happy:-2}}]},
  {l:T('Buy grain and give it away','买粮施舍'),cost:60,out:[{w:2,t:T('Sixty taels of rice, ladled out at your door for a week. Children follow you down the street.','六十两银子的米，在你门口施了一个星期的粥。孩子们跟在你身后满街跑。'),c:'good',fx:{align:6,fame:2,happy:3}},
   {w:s=>s.t.luck*.1+s.fame/60,t:T('One of the families you fed turns out to be a retired official’s. He writes a poem about you that is sung in three counties.','你接济过的人家里，有一户是告老还乡的官。他写了首诗夸你，三个县都传唱开了。'),c:'gold',fx:{align:5,fame:5}}]}]});

I({id:'so_petition',age:[18,80],cd:12,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,age:rint(55,75)});return c},
 text:c=>T(`The village elders, led by old ${c.npc.en}, have a petition about the river dike. The county magistrate keeps “losing” it. They want someone who can travel to carry it straight to the prefect.`,`村里的老人们推${c.npc.zh}领头，写了一份修河堤的呈子。县太爷那边一回回地“弄丢”了。他们想托个能走远路的人，直接递到知府手里。`),
 opts:[{l:T('Carry it','替他们送去'),out:[{w:s=>.5+s.fame/25+s.smarts/40,t:T('The prefect reads it at his desk while you wait. A month later, silver for the dike arrives, and the magistrate is suddenly very interested in rivers.','知府当着你的面看完了呈子。一个月后，修堤的银子拨下来了，县太爷也忽然对河道上了心。'),c:'good',fx:{fame:3,align:3}},
   {w:1,t:T('The magistrate’s men meet you on the road. You lose the petition and a tooth.','半路上，县太爷的人截住了你。呈子丢了，牙也掉了一颗。'),c:'bad',fx:{hurt:[3,8],cause:T('the magistrate’s thugs','县衙的打手'),looks:-1}}]},
  {l:T('Rewrite it first','先替他们改一改'),if:s=>s.smarts>=40,out:[{w:s=>s.smarts/20,t:T('Your version is so clear the prefect quotes it in a memorial to the throne. The elders frame a copy.','你改过的呈子条理分明，知府把其中几句直接抄进了给朝廷的奏折。老人们把底稿裱了起来。'),c:'gold',fx:{smarts:1,fame:4,align:2}},
   {w:1,t:T('Too well written: the clerk decides a disgraced scholar must be behind it and files it under “trouble”.','写得太好了：书办断定背后有个落第的刁生，把它归进了“滋事”那一档。'),c:'bad',fx:{happy:-2}}]},
  {l:T('Decline','推辞'),out:[{w:1,t:T('They thank you anyway and ask a carter.','他们照样谢了你，转头去托一个赶车的。'),c:'muted'},
   {w:s=>s.t.luck*.1,t:T('The carter gets through, and is a village hero for the rest of his life. He tells the story at every wedding.','赶车的竟送到了，从此成了村里的大功臣。每逢喜事，他都要把这段讲一遍。'),c:'muted',fx:{happy:-1}}]}]});

I({id:'so_witness',age:[16,80],cd:10,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:26,age:rint(35,55)});return c},
 text:c=>T(`You saw a rich family’s carriage run down a porter in the street. Now the porter is dead, the yamen wants witnesses, and the family’s steward, ${c.npc.en}, has pressed a purse into your hand on the steps.`,`你亲眼看见一户大户人家的马车在街上撞倒了一个挑夫。如今挑夫死了，衙门在找证人。那家的管家${c.npc.zh}在衙门台阶上，往你手里塞了一个钱袋。`),
 opts:[{l:T('Tell the truth','照实说'),out:[{w:s=>s.align>20?3:1.5,t:T('The magistrate orders the family to pay the porter’s widow fifty taels. The steward watches you all the way down the steps.','县太爷判那家赔挑夫的寡妇五十两。管家一路盯着你走下台阶。'),c:'good',fx:{align:4,fame:1}},
   {w:s=>s.fame<20?1.5:.6,t:T('The magistrate thanks you and finds for the family anyway. At least the widow knows someone spoke up.','县太爷谢了你，还是判那家无罪。好歹那寡妇知道，有人替她说过话。'),c:'muted',fx:{align:3,happy:-3}}]},
  {l:T('Keep the purse and forget','收下钱袋，忘了这事'),out:[{w:2,t:T('Thirty taels. You saw nothing; the porter tripped.','三十两。你什么也没看见，是挑夫自己绊倒的。'),c:'muted',fx:{money:30,align:-4}},
   {w:s=>.3+s.fame/30,t:T('A year later the porter’s son recognises you in the market and spits at your feet. People ask why.','一年后，挑夫的儿子在集上认出了你，一口唾沫吐在你脚边。旁人都问是怎么回事。'),c:'bad',fx:{money:30,align:-5,fame:-2}}]},
  {l:T('Say you saw nothing','推说没看清'),out:[{w:1,t:T('Nobody presses you. You go home early.','没人追问。你早早回了家。'),c:'muted',fx:{align:-2}},
   {w:s=>s.t.heart*.15,t:T('You lie awake for weeks, hearing the wheels.','你好几个星期睡不着，耳边总是车轮声。'),c:'bad',fx:{align:-1,happy:-4}}]}]});

I({id:'so_deserters',age:[16,75],cd:10,tags:['wander'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:28,sex:'m',age:rint(30,45)});c.lv=PW(1,3)(s);return c},
 text:c=>T(`Six men in faded army jackets block the road. Their sergeant, ${c.npc.en}, is almost polite: the frontier has not paid them in three years, so now the road pays them. “A toll, friend. Nothing personal.”`,`六个穿着褪色号衣的汉子拦住了路。领头的伍长${c.npc.zh}几乎算得上客气：边关三年没发饷，如今只好让这条路来发。“朋友，过路钱。不是冲你。”`),
 opts:[{l:T('Fight','动手'),fight:FG((s,c)=>c.lv,'injury',T('Soldiers turned bandits','兵变成匪'),T('the deserters','逃兵'),()=>T('the deserters','逃兵')),
   win:[{w:2,t:T('They fight like soldiers, in a line, and break like soldiers who have not eaten. They scatter into the hills.','他们列阵打得有板有眼，可到底是饿着肚子的兵，一冲就散，钻进了山里。'),c:'good',fx:{fame:2}},
    {w:s=>s.t.heart*.2,t:c=>T(`${c.npc.en} kneels and asks you to kill him rather than hand him over. You give him your dry rations instead.`,`${c.npc.zh}跪下来，求你杀了他，别把他送官。你把干粮给了他。`),c:'muted',fx:{align:3,fame:1}}],
   lose:[{t:T('They take your silver, give you a drink of water, and apologise. Somehow that is worse.','他们拿走了你的银子，给你喝了口水，还道了声歉。不知怎么，这更叫人难受。'),c:'bad',fx:{f:s=>pay(s,-Math.min(s.money,rint(20,60))),hurt:[3,9],cause:T('deserters','逃兵')}}]},
  {l:T('Pay the toll','交过路钱'),cost:15,out:[{w:2,t:T('He gives you a receipt in neat army script. You keep it as a curiosity.','他给你写了张收条，用的是工工整整的军中字体。你留着当个稀罕物。'),c:'muted',fx:{happy:1}},
   {w:s=>s.t.luck*.15,t:T('In return he warns you: real bandits wait at the next pass. You take the long road and live to tell it.','作为回报，他提醒你：下一个山口有真土匪。你绕了远路，躲过一劫。'),c:'good',fx:{happy:2}}]},
  {l:T('Tell them where an amnesty is posted','告诉他们哪里贴着招安告示'),out:[{w:s=>s.smarts/30+s.fame/40,t:T('They go to the county seat. Months later you hear the magistrate took them on as militia, and the sergeant has a new jacket.','他们去了县城。几个月后你听说，县里把他们收编成了乡勇，伍长也换了身新号衣。'),c:'good',fx:{align:4,fame:1}},
   {w:1.2,t:T('They laugh. “We tried that. That’s how we got here.” They take ten taels for the advice.','他们哈哈大笑。“试过了，就是这么试到这儿来的。”说完收了你十两，算是听你讲话的钱。'),c:'muted',fx:{money:-10,happy:-1}}]}]});

/* =========================== the yamen: accused, hired, watched =========================== */
I({id:'so_accused1',age:[16,70],cd:15,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:9,age:rint(30,50)});c.mag=npc(s,{sex:'m',age:rint(45,60)});return c},
 text:c=>T(`A merchant at your inn wakes to find his silver gone. You are the only stranger in the house, so Constable ${c.npc.en} comes for you before breakfast.`,`客栈里一个客商一觉醒来，银子不见了。满店只有你一个外乡人，于是捕头${c.npc.zh}没等早饭就找上了你。`),
 opts:[{l:T('Go quietly to the yamen','老老实实去衙门'),out:[{w:2,t:T('They chain your wrists and walk you through the market.','他们给你上了锁链，押着你穿过集市。'),c:'muted',next:'so_accused2',keep:1},
   {w:s=>s.fame/25,t:T('The constable knows your name and does not chain you. He seems embarrassed.','捕头听过你的名字，没给你上锁，看上去还有些不好意思。'),c:'muted',fx:{f:(s,c)=>{c.kind=1}},next:'so_accused2',keep:1}]},
  {l:T('Run for it','跑'),out:[{w:s=>s.t.luck*.2+power(s)/80,t:T('Over the back wall and into the reeds. By evening your description is on every gate.','翻过后墙，钻进芦苇荡。到傍晚，各个城门都贴上了你的模样。'),c:'bad',fx:{wanted:1,fame:-1}},
   {w:1,t:T('You get as far as the stable. Now you look guilty, too.','你只跑到马厩就被按住了。这下看起来更像是你干的。'),c:'bad',fx:{hurt:[3,8],cause:T('the constables','捕快')},next:'so_accused2',keep:1}]},
  {l:T('Ask for one hour to find the real thief','求给一个时辰找出真贼'),out:[{w:s=>s.smarts/25+s.t.wit*.1,t:T('Wet footprints, a loose floorboard, and the cook’s nephew with new boots. The merchant gets his silver and gives you ten taels of it.','湿脚印、松动的地板，还有厨子侄儿脚上那双新靴子。客商找回了银子，分了你十两。'),c:'good',fx:{money:10,fame:2,smarts:1}},
   {w:1.2,t:T('You find nothing but more suspicion. The hour is up.','什么也没找到，只找来更多怀疑。一个时辰到了。'),c:'muted',next:'so_accused2',keep:1}]}]});
I({id:'so_accused2',only:1,noThread:1,
 text:c=>c.kind?T(`Magistrate ${c.mag.en} looks bored. “Explain yourself, and be quick. I have a lunch.”`,`县太爷${c.mag.zh}一脸不耐烦。“有什么话快说，本官还要用午饭。”`)
  :T(`The yamen hall is cold. Magistrate ${c.mag.en} bangs the gavel block. “Kneel. The thief always says he is innocent, so save your breath, or confess and save mine.”`,`衙门大堂阴冷。县太爷${c.mag.zh}一拍惊堂木。“跪下。贼都说自己冤枉，省省你的口水，要么招了，省省本官的。”`),
 opts:[{l:T('Argue your case','据理申辩'),out:[{w:s=>s.smarts/25+(s.fame>=25?1:0),t:T('You ask why a thief would stay for breakfast. You ask where the silver is. The magistrate cannot answer either, and lets you go.','你问：贼偷了银子，为什么还留下来吃早饭？你又问：银子在哪儿？县太爷答不上来，只好放人。'),c:'good',fx:{happy:3,fame:1}},
   {w:1.3,t:T('He hears you out, nods, and sentences you to a year. Somebody has to be guilty.','他听你说完，点点头，判了你一年。总得有个人是贼。'),c:'bad',fx:{jail:1}}]},
  {l:T('Bribe the clerk','打点书办'),cost:50,out:[{w:s=>1.5+s.smarts/60,t:T('The clerk finds a “witness” who saw a man in a blue coat. You are released before dark.','书办找来一个“证人”，说看见一个穿蓝褂子的人。你天黑前就出来了。'),c:'muted',fx:{align:-2}},
   {w:s=>s.t.luck<4?1.5:.4,t:T('The clerk pockets the silver and you still get twenty strokes of the heavy rod.','书办收了银子，你照样挨了二十大板。'),c:'bad',fx:{hurt:[6,12],cause:T('the heavy rod','大板'),f:s=>addCond(s,'wound',1)}}]},
  {l:T('Say nothing and take the rod','一言不发，挨板子'),out:[{w:s=>s.t.root*.2,t:T('Twenty strokes. You do not make a sound. The magistrate, unsettled, rules there is not enough evidence.','二十大板，你一声没吭。县太爷心里发毛，判了个“证据不足”。'),c:'muted',fx:{hurt:[5,10],cause:T('the heavy rod','大板'),fame:1}},
   {w:1,t:T('Twenty strokes, and then twenty more. You limp out with a judgement of “released, under suspicion”.','二十大板，又是二十大板。你一瘸一拐地出了衙门，判词是“暂释，存疑”。'),c:'bad',fx:{hurt:[8,16],cause:T('the heavy rod','大板'),f:s=>addCond(s,'wound',1)}}]}]});

I({id:'so_muscle',age:[20,60],cd:15,once:1,when:s=>power(s)>=35,ctx:s=>{const c=scene();c.npc=npc(s,{sex:'m',age:rint(40,58)});c.honest=chance(.35);return c},
 text:c=>T(`Magistrate ${c.npc.en} invites you to dinner. He has heard what you can do with your hands. “This county is full of rogues. I need a strong right arm, and I pay well.”`,`县太爷${c.npc.zh}请你吃饭，说听闻你身手了得。“本县刁民太多，本官缺一条硬胳膊。银子嘛，不会亏待你。”`),
 opts:[{l:T('Take the job','应下这份差事'),out:[{w:(s,c)=>c.honest?2+s.align/50:.2,t:T('To your surprise he means it: you chase off real bandits and a crooked granary keeper. The pay is modest; the sleep is good.','没想到他是真心的：你赶跑了真土匪，还收拾了一个黑心的仓官。银子不多，觉睡得踏实。'),c:'good',fx:{money:40,align:4,fame:2}},
   {w:(s,c)=>c.honest?.3:2,t:T('Within a month you are collecting debts for his brother-in-law and “persuading” tenants. The silver is very good.','不到一个月，你就在替他小舅子收账、去“劝”交不起租的佃户。银子给得真不少。'),c:'muted',fx:{money:[80,160],align:-6,flag:'so_lackey'}},
   {w:s=>s.smarts/40,t:T('You take the post and quietly write down everything he asks you to do.','你应下了差事，暗地里把他叫你干的每一件事都记了下来。'),c:'muted',fx:{money:60,smarts:1,flag:'so_lackey'}}]},
  {l:T('Accept, but not against the poor','可以，但不欺负穷人'),out:[{w:s=>.3+s.fame/30+Math.max(0,s.align)/60,t:T('He agrees, a little stiffly, and mostly keeps to it.','他有点勉强地答应了，大体上也还守着。'),c:'good',fx:{money:50,align:2}},
   {w:1,t:T('He agrees, and breaks it within a week. By then you are in too deep to walk away clean.','他嘴上答应，一个星期就破了戒。那时你已经陷得太深，没法干干净净地走了。'),c:'bad',fx:{money:50,align:-3,flag:'so_lackey'}}]},
  {l:T('Decline politely','客客气气地推了'),out:[{w:2,t:T('He smiles and pours you more wine. Nothing more is said.','他笑了笑，又给你斟了一杯。这事就没再提。'),c:'muted'},
   {w:s=>s.fame<15?1.2:.3,t:T('He remembers. Every permit you need from the yamen now takes a year and a fee.','他记下了。从此你去衙门办什么事，都得等一年，还得交份钱。'),c:'bad',fx:{money:-20,happy:-2}}]}]});
I({id:'so_muscle2',age:[20,75],w:6,once:1,need:'so_lackey',when:soAfter('so_lackey'),ctx:s=>{const c=scene();c.npc=npc(s,{sex:'m',age:rint(50,65)});return c},
 text:c=>T(`An imperial censor, ${c.npc.en}, arrives to look into the magistrate you work for. That night the magistrate sends for you: three witnesses are talking too much, and he would like them to stop.`,`朝廷派了一位御史${c.npc.zh}来查你效力的那位县太爷。当夜县太爷就把你叫了去：有三个证人嘴太松，他希望他们闭嘴。`),
 opts:[{l:T('Testify against him','反戈一击，去作证'),out:[{w:s=>.5+s.smarts/30+s.fame/40,t:T('Your notes are better than anything the censor dug up. The magistrate goes to the capital in a cage cart, and you are pardoned for what you did under orders.','你记下的东西，比御史查到的还全。县太爷被关进囚车押往京城，你奉命做过的事也一笔勾销了。'),c:'good',fx:{align:8,fame:3,unflag:'so_lackey'}},
   {w:1,t:T('The censor takes your testimony, and the magistrate’s gold. In the end only the hired arm is punished.','御史收了你的证词，也收了县太爷的金子。到头来，挨罚的只有你这个打手。'),c:'bad',fx:{align:4,wanted:1,hurt:[4,10],cause:T('a beating at the yamen','衙门里的一顿打'),unflag:'so_lackey'}}]},
  {l:T('Do as he asks','照他说的办'),out:[{w:2,t:T('The witnesses remember nothing. The censor leaves. The magistrate gives you a hundred and twenty taels and calls you his nephew.','证人什么都记不起来了。御史走了。县太爷赏了你一百二十两，还管你叫贤侄。'),c:'muted',fx:{money:120,align:-8,unflag:'so_lackey'}},
   {w:s=>(11-s.t.luck)*.12,t:T('He falls anyway, a year later, and names you first to save himself.','一年后他还是倒了，为了自保，头一个就供出了你。'),c:'bad',fx:{align:-8,jail:1,unflag:'so_lackey'}}]},
  {l:T('Disappear before anyone asks','趁没人问，一走了之'),out:[{w:2,t:T('You leave the county by night. You will not be going back.','你连夜出了县境，再也不会回去了。'),c:'muted',fx:{happy:-2,unflag:'so_lackey'}},
   {w:s=>s.fame/40,t:T('Both sides send men after you: one to silence you, one to make you talk. You talk to neither.','两边都派人找你：一边要你闭嘴，一边要你开口。你谁也没理。'),c:'bad',fx:{enemy:1,unflag:'so_lackey'}}]}]});

I({id:'so_inspector1',age:[16,80],cd:15,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,sex:'m',age:rint(55,70)});c.who=chance(.6)?'insp':'spy';return c},
 text:c=>T(`At the teahouse an old man with soft hands and very good boots sits at your table. He says he sells tea. Then he asks what people here really think of the magistrate.`,`茶馆里，一个手很细、靴子很好的老头在你桌边坐下。他说自己是贩茶的。接着就问，本地人到底怎么看县太爷。`),
 opts:[{l:T('Tell him the truth','照实说'),out:[{w:2,t:T('You tell him about the taxes, the beatings and the garden built with bridge money. He listens without touching his tea.','你讲了苛税、板子，还有拿修桥钱修的花园。他听着，茶一口没动。'),c:'muted',fx:{f:(s,c)=>{c.told=1}},next:'so_inspector2',keep:1},
   {w:s=>s.smarts/40,t:T('You notice the boots, and tell him the truth in a way that could be taken as a joke.','你留意到他那双靴子，便把实话说得像是在说笑。'),c:'muted',fx:{f:(s,c)=>{c.told=1;c.careful=1}},next:'so_inspector2',keep:1}]},
  {l:T('Praise the magistrate','夸县太爷几句'),out:[{w:2,t:T('“A father to us all,” you say. He nods slowly, pays for your tea, and leaves.','“爱民如子啊。”你说。他慢慢点了点头，替你付了茶钱，走了。'),c:'muted',next:'so_inspector2',keep:1},
   {w:s=>s.t.heart*.1,t:T('The words taste bad. You change the subject to the weather.','这话说出口就觉得不是味儿。你把话题扯到了天气上。'),c:'muted',fx:{happy:-1},next:'so_inspector2',keep:1}]},
  {l:T('Ask him who he really is','问他到底是什么人'),out:[{w:s=>s.smarts/25+s.t.wit*.1,t:c=>c.who==='insp'?T('He laughs. “You have sharp eyes. Keep them open and your mouth shut for three days.”','他笑了。“好眼力。三天之内，把眼睛睁大，嘴闭紧。”'):T('He laughs a little too quickly, and leaves a little too soon.','他笑得太快了点，走得也太早了点。'),c:'muted',fx:{f:(s,c)=>{c.careful=1}},next:'so_inspector2',keep:1},
   {w:1,t:T('“Tea,” he says. “I sell tea.” He changes the subject.','“茶，”他说，“我是卖茶的。”说完就岔开了话。'),c:'muted',next:'so_inspector2',keep:1}]}]});
I({id:'so_inspector2',only:1,noThread:1,
 text:c=>c.who==='insp'?T('Three days later the old man rides through the gate in a purple robe with forty guards: an Imperial Inspector. By evening the magistrate is in chains, and a runner comes to your door with an invitation.','三天后，老头穿着紫袍、带着四十名护卫进了城门：原来是钦差巡按。当晚县太爷就戴上了枷锁，一个差役来到你门口，说大人有请。')
  :T('Three days later constables knock on your door. The old man was the magistrate’s ear, and he has reported every word.','三天后，捕快敲响了你的门。那老头是县太爷的耳目，你说过的每一个字，他都报上去了。'),
 opts:[{l:T('Answer the summons','应召前去'),if:(s,c)=>c.who==='insp',out:[{if:(s,c)=>c.told,w:s=>1+s.fame/40,t:T('“You were the only one who told me the truth,” he says. He gives you fifty taels and a letter that will open yamen doors for years.','“只有你跟我说了实话。”他说。他赏了你五十两，还给了一封信，往后几年衙门的门都会为你开。'),c:'gold',fx:{money:50,fame:3,align:3}},
   {if:(s,c)=>c.told,w:s=>s.smarts/40,t:T('He questions you for an hour about the county, then asks if you would like to be his runner. You say you will think about it. He pays you anyway.','他问了你一个时辰的县情，又问你愿不愿意给他当差。你说想想。他还是给了你赏钱。'),c:'good',fx:{money:30,smarts:2,fame:2}},
   {if:(s,c)=>!c.told,w:1,t:T('“You were afraid,” he says, “and you were right to be. That is what is wrong with this county.” He lets you go.','“你怕了，”他说，“你怕得没错。这个县的毛病就在这里。”他让你走了。'),c:'muted',fx:{happy:-1}},
   {if:(s,c)=>!c.told,w:s=>s.t.luck*.1,t:T('He remembers you anyway, as the one who asked who he was. He sends a small gift for the sharp eyes.','他还是记得你，记得你是那个问他是谁的人。他送来一份薄礼，说是赏你眼尖。'),c:'good',fx:{money:20}}]},
  {l:T('Stay away from it all','躲远点'),if:(s,c)=>c.who==='insp',out:[{w:2,t:T('You watch the magistrate’s cage cart leave town from a rooftop.','你在屋顶上看着县太爷的囚车出了城。'),c:'muted',fx:{happy:2}},
   {w:s=>s.fame/40,t:T('The new magistrate is told you refused the Inspector’s summons. He wonders why.','新来的县太爷听说你没应钦差的召。他琢磨这是为什么。'),c:'muted',fx:{fame:-1}}]},
  {l:T('Deny everything','死不认账'),if:(s,c)=>c.who==='spy',out:[{if:(s,c)=>c.told,w:s=>s.smarts/25+.2,t:T('You call it tavern talk and make the constables laugh. They let you off with a warning.','你说那是茶馆闲话，还把捕快们逗乐了。他们训了你几句就放了。'),c:'muted',fx:{happy:-1}},
   {if:(s,c)=>c.told,w:(s,c)=>c.careful?.5:1.5,t:T('Twenty strokes for slandering an official, and your name in the yamen book.','以“诽谤官长”的罪名打了二十板，名字也记进了衙门的簿子。'),c:'bad',fx:{hurt:[5,11],cause:T('the yamen rod','衙门的板子'),wanted:1}},
   {if:(s,c)=>!c.told,w:1,t:T('There is nothing to deny. The constables apologise and go.','本来就没什么可认的。捕快们道了个歉，走了。'),c:'muted'},
   {if:(s,c)=>!c.told,w:s=>s.t.luck*.1,t:T('The magistrate sends you a gift for your “loyal words”. You feel faintly sick.','县太爷派人送来一份礼，说是谢你的“忠言”。你心里有点犯恶心。'),c:'muted',fx:{money:20,align:-2}}]},
  {l:T('Go out the back','从后门溜'),if:(s,c)=>c.who==='spy',out:[{w:s=>s.t.luck*.2+power(s)/80,t:T('You are two counties away by morning, and the magistrate has other things to do than chase you.','天亮时你已经在两个县之外了，县太爷也没闲工夫追你。'),c:'muted',fx:{happy:-2}},
   {w:1,t:T('They are waiting at the back, too. Running makes it worse.','后门也有人守着。一跑，事情更糟了。'),c:'bad',fx:{hurt:[4,10],cause:T('the constables','捕快'),wanted:1}}]}]});

I({id:'so_examhall',age:[16,65],cd:15,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:1,age:rint(20,30)});return c},
 text:c=>T(`The prefectural exams are next month. A proctor’s servant is quietly selling the questions for a hundred taels. Your cousin is sitting the exam, and so is a penniless scholar you know, ${c.npc.en}, who has failed four times.`,`府试就在下个月。有个考官的家仆在暗地里卖考题，一百两一份。你表弟要考，你认识的穷书生${c.npc.zh}也要考，${c.npc.ta}已经落第四回了。`),
 opts:[{l:T('Buy the questions for your cousin','给表弟买一份'),cost:100,out:[{w:s=>s.t.luck*.2,t:T('The questions are real. Your cousin passes, and your family’s standing rises a little. You do not ask what happened to the scholar.','考题是真的。表弟中了，家里的脸面也长了些。那个书生怎么样了，你没问。'),c:'muted',fx:{happy:4,align:-4,fame:1}},
   {w:1,t:T('The questions are fake. A hundred taels for a page of nonsense.','考题是假的。一百两，换了一张胡言乱语。'),c:'bad',fx:{happy:-4}},
   {w:.5,t:T('A scandal breaks: everyone who bought questions is named and caned. Including the one who paid.','事发了：凡是买过考题的，一个个点名挨板子。掏钱的那个也跑不了。'),c:'bad',fx:{align:-3,wanted:1,hurt:[4,8],cause:T('the exam scandal','科场案')}}]},
  {l:T('Report the proctor','去告发考官'),out:[{w:s=>.4+s.fame/25+s.smarts/50,t:T('The exam is postponed, the proctor exiled, and the scholars of three counties drink to your health.','考期推后，考官发配，三个县的读书人都举杯敬你。'),c:'good',fx:{fame:4,align:4}},
   {w:1,t:T('The official you report to is the proctor’s uncle. You are thrown out of the yamen and down its steps.','你告到的那位大人，偏偏是考官的亲舅舅。你被轰出衙门，还从台阶上滚了下去。'),c:'bad',fx:{hurt:[4,9],cause:T('the yamen steps','衙门的台阶'),happy:-3}}]},
  {l:T('Tell the poor scholars and let them decide','告诉穷书生们，让他们自己拿主意'),out:[{w:s=>s.t.heart*.25,t:c=>T(`${c.npc.en} and forty others march on the exam hall with their inkstones. The exam is set again with new questions. ${c.npc.en} passes, at last.`,`${c.npc.zh}领着四十来个书生，捧着砚台围了贡院。考试重新出题。这一回，${c.npc.zh}总算中了。`),c:'good',fx:{fame:2,align:3,meet:'friend',bond:65}},
   {w:1,t:T('They talk about it for a week, write some furious poems, and do nothing.','他们议论了一个星期，写了几首义愤填膺的诗，然后什么也没做。'),c:'muted',fx:{smarts:1}}]}]});

I({id:'so_courtcase',age:[20,90],cd:15,ctx:s=>{const c=scene();c.a=npc(s,{occ:0,sex:'m',age:rint(40,60)});c.b=npc(s,{occ:5,sex:'m',age:rint(40,60)});return c},
 text:c=>T(`Two families you have known for years, ${c.a.en}’s and ${c.b.en}’s, have gone to law over a hillside where both say their ancestors are buried. Both have sent you gifts. Both expect you to testify for them.`,`你认识多年的两户人家，${c.a.zh}家和${c.b.zh}家，为一面山坡打起了官司，两家都说祖坟埋在那里。两家都给你送了礼，都指望你替自己作证。`),
 opts:[{l:T('Testify plainly to what you know','知道什么说什么'),out:[{w:s=>s.smarts/30+s.fame/40,t:T('What you know settles it. The losing side grumbles, but in a year they are invited to the same weddings again.','你说的话定了案。输的那家嘀咕了一阵，一年后两家又在同一个喜宴上碰杯了。'),c:'good',fx:{fame:2,align:3}},
   {w:1,t:T('The losing family cuts you dead in the street and returns your New Year cakes uneaten.','输的那家在街上见了你扭头就走，过年送去的糕点原封不动地退了回来。'),c:'muted',fx:{align:2,happy:-3}}]},
  {l:T('Broker a settlement out of court','私下说和'),out:[{w:s=>s.smarts/25+s.looks/60+s.fame/50,t:T('Three dinners, much wine, and one marriage between a son and a daughter. The hill is now a family grave for both.','三顿饭，喝了不少酒，又撮合了两家一儿一女。如今那面山坡，成了两家共同的祖茔。'),c:'good',fx:{fame:3,happy:3}},
   {w:1.3,t:T('The talks end in a brawl in the ancestral hall. You leave with a black eye and both sets of gifts returned.','说和说到后来，在祠堂里打成一团。你顶着个乌眼圈回来，两家的礼都退回来了。'),c:'bad',fx:{hurt:[2,6],cause:T('a family brawl','宗族斗殴'),looks:-1}}]},
  {l:T('Keep both gifts and stay out of it','两份礼都收下，躲着不出面'),out:[{w:2,t:T('Forty taels of gifts, and a sudden need to visit relatives far away.','四十两的礼，外加一趟忽然非走不可的远门。'),c:'muted',fx:{money:40,align:-4}},
   {w:s=>.4+s.fame/40,t:T('The two families compare notes. For once, they agree about something: you.','两家一对账，头一回意见一致——都说你不是东西。'),c:'bad',fx:{money:40,align:-4,fame:-3}}]}]});

I({id:'so_plague',age:[16,90],cd:15,w:s=>soWd(s).h<=-1?1.6:.6,ctx:s=>{const c=scene();c.npc=npc(s,{occ:10,age:rint(40,65)});c.lv=PW(.85,0)(s);return c},
 text:(c,s)=>T(`A fever is spreading through ${soRg(s).en}. The town gates are shut. The physician ${c.npc.en} has turned a temple into a sickhouse and is asking for anyone with strong arms and no fear.`,`${soRg(s).cn}闹起了瘟疫。城门关了。郎中${c.npc.zh}把一座庙改成了病坊，到处找胳膊有劲、胆子够大的人帮手。`),
 opts:[{l:T('Help in the sickhouse','去病坊帮忙'),out:[{w:s=>1+s.t.root*.2,t:T('For a month you carry the sick and bury the dead. The fever burns out. The physician bows to you in the street.','一个月里，你抬病人，埋死人。瘟疫总算熄了。郎中在街上见了你，深深一揖。'),c:'good',fx:{align:6,fame:3}},
   {w:1,t:T('You catch it yourself. You live, but only just.','你自己也染上了。命是保住了，也只是刚刚保住。'),c:'bad',fx:{align:5,ill:'fever',hurt:[6,14],cause:T('the plague','瘟疫')}}]},
  {l:T('Guard the quarantine gate','去守隔离的城门'),out:[{w:s=>.5+power(s)/40,t:T('Nobody gets in or out without the physician’s chalk mark. Some curse you. The plague stays inside one ward.','没有郎中的粉笔记号，谁也不许进出。有人骂你。瘟疫被关在了一个坊里。'),c:'good',fx:{align:2,fame:2}},
   {w:1,t:T('A father desperate to reach his children comes at you with a hoe. You stop him, and carry the scar.','一个急着见孩子的父亲抡着锄头扑上来。你拦住了他，自己落了道疤。'),c:'bad',fx:{hurt:[5,12],cause:T('a desperate father','一个急疯了的父亲'),looks:-2,f:s=>addCond(s,'wound',1)}}]},
  {l:T('Get out while you can','趁早离开'),out:[{w:s=>s.t.luck*.2,t:T('You find a hole in the wall and a cart going north. Behind you, the town burns its dead.','你找到城墙上一处破口，搭上一辆往北的车。身后，城里在烧死人。'),c:'muted',fx:{happy:-2,align:-2}},
   {w:1,t:T('You get out. The fever comes with you.','你出来了。瘟疫也跟着你出来了。'),c:'bad',fx:{ill:'fever',align:-2}}]},
  {l:T('Sell herbs at plague prices','高价卖药材'),if:s=>s.money>=30,out:[{w:s=>s.smarts/30+1,t:T('Willow bark at ten times its price. You get rich in a fortnight.','柳树皮卖到十倍的价钱。半个月你就发了财。'),c:'muted',fx:{money:[60,150],align:-6}},
   {w:s=>s.fame/30+.5,t:T('A crowd works out what you are doing. They take your stock and give you a beating for free.','人们看出了你在干什么。药材被抢了，还白送你一顿打。'),c:'bad',fx:{fame:-3,hurt:[4,10],cause:T('an angry crowd','愤怒的人群')}}]}]});

I({id:'so_locust',age:[16,90],cd:15,w:s=>(['north','central','capital'].includes(s.region)?1:.4)*(soWd(s).h<=-1?2:1),ctx:s=>{const c=scene();c.npc=npc(s,{sex:'m',age:rint(45,60)});return c},
 text:c=>T(`A brown cloud comes over the hills, and the sound is like rain. Locusts. Magistrate ${c.npc.en} forbids anyone to kill them: they are heaven’s punishment, and must be prayed away. He orders an altar built.`,`山那边飘过来一片黄云，声音像下雨。是蝗虫。县太爷${c.npc.zh}下令不许扑杀，说这是上天降罚，只能祷告送走。他叫人搭起了祭坛。`),
 opts:[{l:T('Dig trenches and light fires anyway','照样挖沟点火'),out:[{w:s=>.5+s.smarts/30+s.fame/40,t:T('Three villages follow you. Trenches, smoke and brooms save half the harvest. The magistrate decides it was his prayers.','三个村跟着你干。挖沟、熏烟、扫帚扑，保住了一半庄稼。县太爷说，这是他祷告灵验了。'),c:'good',fx:{align:4,fame:3}},
   {w:1,t:T('You save the fields of one village, and are flogged at the altar for impiety.','你保住了一个村的地，自己却在祭坛前以“亵渎上天”的罪名挨了鞭子。'),c:'bad',fx:{align:3,fame:1,hurt:[4,10],cause:T('a flogging','一顿鞭刑')}}]},
  {l:T('Join the prayers','跟着去祷告'),out:[{w:1.5,t:T('The locusts eat everything to the roots. Rice doubles in price by winter.','蝗虫把庄稼啃得只剩根。入冬时米价翻了一番。'),c:'bad',fx:{happy:-3,money:-15}},
   {w:s=>s.t.luck*.12,t:T('The wind turns on the third day and the cloud drifts on to the next county. Everyone is very pleased with the gods, except the next county.','第三天风向变了，蝗群飘去了邻县。大家都说老天有眼，邻县的人除外。'),c:'good',fx:{happy:4}}]},
  {l:T('Catch them and fry them','抓来油炸了卖'),out:[{w:s=>.5+s.smarts/40,t:T('Fried locust with salt and pepper, three coppers a skewer. The hungry buy, the brave buy twice.','椒盐炸蚂蚱，三文钱一串。饿的人买，胆大的买两串。'),c:'good',fx:{money:[20,50],happy:2}},
   {w:1,t:T('Nobody will eat heaven’s punishment. You eat well for a week.','没人敢吃老天的惩罚。你自己吃了一个星期，吃得挺好。'),c:'muted',fx:{happy:1,heal:3}}]}]});

I({id:'so_prisonriot',age:[18,70],cd:15,tags:['town'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:19,sex:'m',age:rint(65,80)});c.lv=PW(.95,3)(s);return c},
 text:()=>T('You are at the county jail with a basket of food for an acquaintance when the prisoners rise. Keys are snatched, a guard goes down, and the corridor fills with shouting men.','你提着一篮吃食去县牢看一个熟人，正赶上犯人暴动。钥匙被抢，一个狱卒倒在地上，走廊里挤满了喊叫的人。'),
 opts:[{l:T('Help the guards hold the gate','帮狱卒守住大门'),fight:FG((s,c)=>c.lv,'injury',T('Riot in the county jail','县牢暴动'),T('rioting prisoners','暴动的犯人'),()=>T('the rioters','暴动的犯人')),
   win:[{w:2,t:T('You hold the gate until the constables arrive. The magistrate gives you thirty taels and a speech.','你一直守到捕快赶来。县太爷赏了你三十两，外加一通训话。'),c:'good',fx:{money:30,fame:3,align:2}},
    {w:s=>s.t.heart*.15,t:T('Afterwards you learn why they rose: no food for nine days. You give the guards the rest of your basket, for the prisoners.','事后你才知道他们为什么闹：九天没给饭吃。你把篮子里剩下的东西交给狱卒，让他们分给犯人。'),c:'muted',fx:{fame:2,align:4}}],
   lose:[{t:T('They go through the gate, and over you.','他们冲出了大门，从你身上踩了过去。'),c:'bad',fx:{hurt:[6,14],cause:T('a prison riot','县牢暴动'),f:s=>addCond(s,'fracture',1)}}]},
  {l:T('Walk out with the crowd','混在人群里出去'),out:[{w:s=>s.t.luck*.2+s.smarts/60,t:T('You slip out in the confusion and walk home. Nobody ever asks.','你趁乱溜了出来，走回了家。没人问起过。'),c:'muted'},
   {w:1,t:T('Next week your face is on the notice board among the escaped prisoners.','第二个星期，你的画像跟逃犯们贴在了一起。'),c:'bad',fx:{wanted:1}}]},
  {l:T('Shield an old prisoner being trampled','护住一个被踩倒的老犯人'),out:[{w:s=>s.t.luck*.15+s.t.heart*.1,t:c=>T(`${c.npc.en}, a gaunt old man, was once a famous boxer. While the riot burns out, he shows you a breathing method that is worth more than the jail.`,`那个瘦骨嶙峋的老头${c.npc.zh}，当年是个有名的拳师。暴动平息之前，他教了你一手吐纳的法门，比整座牢都值钱。`),c:'gold',fx:{qi:3,skill:1}},
   {w:1,t:c=>T(`${c.npc.en} dies in your arms and whispers where he buried his silver. You find it under a willow, thirty years later than he meant.`,`${c.npc.zh}死在你怀里，临终告诉你他把银子埋在了哪儿。你在一棵柳树下挖到了，比他原本打算的晚了三十年。`),c:'muted',fx:{money:[30,90],align:2}}]}]});

I({id:'so_seal',age:[16,80],once:1,tags:['wander'],
 text:()=>T('In a ravine you find a dead courier, two arrows in his back. In his saddlebag, wrapped in yellow silk, is a jade seal with a dragon on top. An imperial seal, lost on its way to some frontier governor.','你在一道山沟里发现一个死了的驿使，背上插着两支箭。马褡子里有个黄绫包，裹着一方顶上盘龙的玉印。是方御印，送往哪位边关大员的半路上丢了。'),
 opts:[{l:T('Take it to the nearest yamen','送到最近的衙门'),out:[{w:s=>.5+s.fame/30+Math.max(0,s.align)/50,t:T('The magistrate turns pale, then joyful. A reward of a hundred taels comes from the capital, with your name spelled wrong.','县太爷先是脸色煞白，接着喜出望外。京里发来一百两赏银，你的名字还写错了一个字。'),c:'good',fx:{money:100,fame:3,align:3}},
   {w:1,t:T('They decide whoever found the courier probably killed him. A month in a cell, until the real killers are caught selling his horse.','他们认定找到驿使的人八成就是凶手。你在牢里关了一个月，直到真凶卖马时被抓。'),c:'bad',fx:{happy:-5,hurt:[3,8],cause:T('the interrogation','审讯')}}]},
  {l:T('Sell it on the black market','拿到黑市上卖'),out:[{w:s=>s.smarts/30+s.t.luck*.1,t:T('A collector with no questions pays you two hundred taels and leaves by the back door.','一个什么都不问的藏家给了你二百两，从后门走了。'),c:'muted',fx:{money:[150,300],align:-6,wanted:1}},
   {w:1,t:T('The buyer is an agent of the Inner Watch. You get away, without the seal or the money.','买主是内缉司的探子。你逃了出来，印没了，钱也没拿到。'),c:'bad',fx:{wanted:2,hurt:[5,12],cause:T('agents of the Inner Watch','内缉司的探子')}}]},
  {l:T('Bury it and wait','先埋起来，等等看'),out:[{w:s=>1+s.smarts/50,t:T('You bury it under a marked stone and memorise the place.','你把它埋在一块做了记号的石头底下，把地方记得牢牢的。'),c:'muted',fx:{flag:'so_sealhid'}},
   {w:s=>s.t.luck*.08,t:T('You bury it, and are sure a shepherd boy saw you. You bury it again, somewhere else.','埋好后，你总觉得有个放羊娃看见了。你又挖出来，换了个地方埋。'),c:'muted',fx:{flag:'so_sealhid',happy:-1}}]}]});
I({id:'so_seal2',age:[17,90],w:6,once:1,need:'so_sealhid',when:soAfter('so_sealhid'),
 text:()=>T('Notices go up in every town: five hundred taels, no questions asked, for the return of a lost imperial seal. People say the Inner Watch is watching every man who comes to claim it.','各处城镇都贴出了告示：寻回遗失御印者，赏银五百两，不问来历。可大家都说，凡是去领赏的，内缉司都盯着。'),
 opts:[{l:T('Dig it up and claim the reward','挖出来去领赏'),out:[{w:s=>s.smarts/30+s.t.luck*.15,t:T('You hand it over through a respectable go-between. Five hundred taels, and the go-between takes only fifty.','你托了个体面的中人送上去。赏银五百两，中人只抽了五十。'),c:'gold',fx:{money:450,fame:2,unflag:'so_sealhid'}},
   {w:1,t:T('You are paid, and then followed for a year by men who want to know who you sold it to first.','银子是领到了，可此后一年总有人跟着你，想知道你先前卖给过谁。'),c:'muted',fx:{money:500,wanted:1,happy:-4,unflag:'so_sealhid'}}]},
  {l:T('Leave it where it is','就让它埋着'),out:[{w:2,t:T('The court carves a new seal. Somewhere under a stone, the old one keeps your secret.','朝廷另刻了一方新印。那方旧印仍在石头底下，替你守着这个秘密。'),c:'muted',fx:{unflag:'so_sealhid'}},
   {w:s=>s.t.luck*.1,t:T('A flood moves the stones. You never find the place again, and you are relieved.','一场大水冲乱了石头。你再也没找到那个地方，倒是松了口气。'),c:'muted',fx:{happy:2,unflag:'so_sealhid'}}]}]});

/* =========================== BIG: the flood and the relief grain =========================== */
I({id:'so_flood1',age:[16,85],cd:20,w:s=>(['jiangnan','central','miao','east'].includes(s.region)?1:.5)*(soWd(s).h<=-1?2:1),
 text:(c,s)=>T(`After forty days of rain the river in ${soRg(s).en} is a hand’s width from the top of the dike, and the dike warden has fled with his family. The village looks to whoever is still standing there.`,`连下了四十天的雨，${soRg(s).cn}的河水离堤顶只差一巴掌。管堤的堤长带着一家老小跑了。全村人都看着还站在堤上的人。`),
 opts:[{l:T('Rouse the village to fill sandbags','招呼全村装沙袋'),out:[{w:s=>.5+s.fame/30+s.smarts/40,t:T('Old men, girls and the miller’s ox work through the night at your shouting. At dawn the dike still holds, by a finger.','老人、姑娘，连磨坊的牛都被你吆喝起来，干了一整夜。天亮时，河堤还撑着，只差一指。'),c:'good',fx:{fame:3,align:4,f:(s,c)=>{c.held=1}},next:'so_flood2',keep:1},
   {w:1,t:T('Not enough hands, not enough sacks. At dawn the dike opens like a door.','人手不够，沙袋也不够。天亮时，河堤像一扇门一样被冲开了。'),c:'bad',fx:{align:3},next:'so_flood2',keep:1}]},
  {l:T('Hold the weak section yourself','自己去顶最险的那段'),out:[{w:s=>power(s)/45,t:T('You drive stakes and carry stones like three men. The weak section holds; the water goes round the village.','你打桩、扛石头，一个人顶三个。最险的那段守住了，大水绕村而过。'),c:'gold',fx:{fame:4,align:4,f:(s,c)=>{c.held=1}},next:'so_flood2',keep:1},
   {w:1,t:T('The bank slides out from under your feet. You are swept a mile downstream and wake in a tree.','脚下的堤岸整块滑了下去。你被冲出一里多地，醒来时挂在一棵树上。'),c:'bad',fx:{hurt:[8,16],cause:T('the flood','洪水'),align:2},next:'so_flood2',keep:1}]},
  {l:T('Get your own people to high ground','先把自家人带到高处'),out:[{w:2,t:T('Your family is safe on the hill when the dike breaks. You watch the water take the lower village.','河堤决口时，你家人已经安安稳稳地在山上了。你看着大水吞了下村。'),c:'muted',fx:{align:-1},next:'so_flood2',keep:1},
   {w:s=>s.t.luck*.15,t:T('The rain stops at midnight. The dike holds without you. Nobody says anything, which is worse.','半夜雨停了。没有你，堤也守住了。谁也没说什么，这更难受。'),c:'muted',fx:{align:-2,f:(s,c)=>{c.held=1}},next:'so_flood2',keep:1}]}]});
I({id:'so_flood2',only:1,noThread:1,
 text:c=>c.held?T(`The water goes down. A clerk from the county, ${c.npc.en}, arrives with relief grain for the flooded villages downstream, and you watch half the carts turn off toward his own warehouse.`,`水退了。县里的书办${c.npc.zh}押着赈粮来救济下游被淹的村子，你眼看着一半的粮车拐向了他自家的仓房。`)
  :T(`Half the village is mud. When the relief grain finally comes, with a clerk named ${c.npc.en}, it is mixed with sand, and the good rice is being sold in the next town.`,`半个村子成了烂泥塘。赈粮好不容易来了，押粮的书办叫${c.npc.zh}。米里掺着沙，好米却在邻镇的米铺里卖。`),
 opts:[{l:T('Report him to the magistrate','去县太爷那里告他'),out:[{w:s=>.3+s.smarts/30+s.fame/40,t:T('You bring a sack of sandy rice as evidence. The clerk is arrested, for now. His cousin, a yamen runner, writes down your name.','你扛了一袋掺沙的米当证据。书办被抓了，至少眼下是。他那个在衙门当差的表哥，记下了你的名字。'),c:'good',fx:{align:4,fame:2,flag:'so_flood_q'}},
   {w:1,t:T('The magistrate nods, thanks you, and does nothing. The clerk sends you a sack of good rice, with a note: “For your silence.”','县太爷点头称谢，然后什么也没做。书办倒派人给你送来一袋好米，附了张条子：“封口之资。”'),c:'muted',fx:{align:3,flag:'so_flood_q'}}]},
  {l:T('Take the carts back by force','把粮车抢回来'),fight:FG(PW(.9,3),'injury',T('The relief grain','夺回赈粮'),T('the clerk’s escort','押粮的差役'),()=>T('the clerk’s escort','押粮的差役')),
   win:[{w:2,t:T('You hand out every sack yourself, at the village shrine. The clerk swears you will pay for this.','你在村里的土地庙前，亲手把每一袋粮分了出去。书办发誓要你好看。'),c:'good',fx:{align:6,fame:3,wanted:1,flag:'so_flood_q'}},
    {w:s=>s.fame/30,t:T('The escort recognises you and does not try very hard. The grain reaches the villages, and the clerk has no witnesses.','押粮的差役认出了你，没怎么真打。粮送到了各村，书办连个证人都找不着。'),c:'good',fx:{align:6,fame:2,flag:'so_flood_q'}}],
   lose:[{t:T('They beat you and drive on. The good rice is sold, and the sand is eaten.','他们打倒了你，赶着车走了。好米卖了，沙子进了人的肚子。'),c:'bad',fx:{hurt:[5,12],cause:T('the clerk’s escort','押粮的差役')}}]},
  {l:T('Let it go and dig out your neighbours','不管了，先帮邻居挖屋子'),out:[{w:s=>s.t.root*.2,t:T('A month with a shovel. Your hands are ruined and three families have roofs again.','拿了一个月的铁锹。你的手磨烂了，三户人家又有了屋顶。'),c:'good',fx:{align:3,maxHealth:1}},
   {w:1,t:T('Flood water and bad food: a fever lays you down for the winter.','泡了洪水，又吃不好，一场热病让你躺了一个冬天。'),c:'bad',fx:{align:3,ill:'fever'}}]}]});
I({id:'so_flood3',age:[17,90],w:6,once:1,need:'so_flood_q',when:soAfter('so_flood_q'),ctx:s=>{const c=scene();c.lv=PW(1,5)(s);return c},
 text:()=>T('The county is rebuilding the dike. The clerk from the flood year is back, promoted to dike commissioner, and the new “stone” facing is mostly mud packed into moulds. He sees you on the bank and smiles.','县里在重修河堤。大水那年的书办又回来了，还升了管堤的委员。新砌的“石”堤，大半是泥巴拍进模子里冒充的。他在岸上看见你，笑了笑。'),
 opts:[{l:T('Cut a block open in front of the prefect','当着知府的面劈开一块"石头"'),out:[{w:s=>s.smarts/25+s.fame/30,t:T('Mud spills out over the prefect’s boots. The commissioner is beheaded at the dike he cheated, and the villagers carve your name on the first real stone.','泥浆淌了知府一靴子。管堤委员就在他偷工减料的堤上被砍了头，村民们在第一块真石头上刻了你的名字。'),c:'gold',fx:{fame:6,align:5,unflag:'so_flood_q',deed:T('Exposed the mud dike and had it rebuilt in stone','揭穿泥堤，督造石堤')}},
   {w:1,t:T('The prefect is the commissioner’s patron. You are charged with damaging public works.','知府正是那委员的靠山。你被扣上了“毁坏官工”的罪名。'),c:'bad',fx:{jail:1,align:3,unflag:'so_flood_q'}}]},
  {l:T('Build one section properly, with your own silver','自己掏钱，修好一段'),cost:100,out:[{w:s=>1+s.t.luck*.2,t:T('Two years later the river rises again. Every section breaks but yours, and the village behind it stays dry.','两年后，河水又涨了。别的段全垮了，只有你修的那段没倒，后面的村子一滴水没进。'),c:'gold',fx:{fame:5,align:5,unflag:'so_flood_q',deed:T('Built the one section of dike that held','自费修了唯一没垮的那段河堤')}},
   {w:1,t:T('The flood does not come again in your lifetime. Children fish from your section of wall, and nobody knows why it is different.','此生大水再没来过。孩子们坐在你修的那段堤上钓鱼，谁也不知道它有什么不一样。'),c:'muted',fx:{happy:3,align:3,unflag:'so_flood_q'}}]},
  {l:T('Settle it the jianghu way','按江湖规矩办'),fight:FG((s,c)=>c.lv,'injury',T('The dike commissioner’s guards','管堤委员的护卫'),T('the commissioner’s guards','委员的护卫'),()=>T('the commissioner’s guards','委员的护卫')),
   win:[{w:2,t:T('You hang him by his ankles from the dike until he confesses to the whole village. He is dismissed; you are wanted.','你倒吊着他挂在堤上，直到他当着全村人认了罪。他被革了职，你上了通缉榜。'),c:'good',fx:{fame:4,align:3,wanted:1,unflag:'so_flood_q'}},
    {w:s=>s.smarts/40,t:T('In his office you find the ledgers. You send them to the prefecture with no name attached, and he is gone within a month.','你在他的公房里翻出了账本，不署名寄到了府里。不到一个月，他就没了踪影。'),c:'good',fx:{fame:2,align:4,unflag:'so_flood_q'}}],
   lose:[{t:T('His guards throw you down the dike. You land badly on the new “stone”.','护卫把你从堤上扔了下去。你重重摔在新砌的“石头”上。'),c:'bad',fx:{hurt:[8,16],cause:T('a fall from the dike','从堤上摔下'),unflag:'so_flood_q',f:s=>addCond(s,'fracture',1)}}]}]});

/* =========================== BIG: the peasant rising =========================== */
I({id:'so_rise1',age:[18,65],once:1,w:s=>(soWd(s).u>=1||soWd(s).h<=-1)?1.6:.5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:0,sex:'m',age:rint(30,45)});return c},
 text:(c,s)=>T(`Three bad harvests and a new grain tax have set the villages of ${soRg(s).en} boiling. ${c.npc.en}, a woodcutter with hands like roots, brings you a scroll with three hundred thumbprints on it. “We need someone who can fight. Lead us.”`,`连着三年歉收，又加了一道粮税，${soRg(s).cn}的村子都快炸锅了。樵夫${c.npc.zh}，一双手像老树根，捧来一卷按满了三百个手印的纸。“我们缺一个会打的人。你来领头吧。”`),
 opts:[{l:T('Lead them','领头'),out:[{w:s=>.3+s.fame/30+power(s)/60,t:T('Word spreads that you have joined. In a month two thousand men are drilling with hoes in the hills.','你入伙的消息一传开，一个月里就聚了两千人，在山里拿着锄头操练。'),c:'gold',fx:{align:3,fame:3,wanted:1,flag:'so_rebel',meet:'sworn',bond:70}},
   {w:1,t:T('Only three hundred come, but they are yours, and they will not go home now.','只来了三百人，可他们认你，如今也回不去了。'),c:'muted',fx:{align:2,wanted:1,flag:'so_rebel',meet:'friend',bond:65}}]},
  {l:T('Warn the magistrate','去给县太爷报信'),out:[{w:s=>.5+s.smarts/40,t:T('The ringleaders are arrested before they move. The magistrate gives you fifty taels and says he may need you again.','领头的还没动手就被抓了。县太爷赏了你五十两，说往后可能还用得着你。'),c:'muted',fx:{money:50,align:-4,flag:'so_loyal'}},
   {w:1,t:c=>T(`The magistrate hangs ${c.npc.en} at the crossroads. The villages remember who carried the message.`,`县太爷把${c.npc.zh}吊死在了十字路口。各村都记得，是谁去报的信。`),c:'bad',fx:{align:-6,fame:-2,flag:'so_loyal'}}]},
  {l:T('Talk them into a petition instead','劝他们先递状子'),out:[{w:s=>s.smarts/30+s.fame/40,t:T('Your petition, signed by every village, reaches the prefect. The new tax is “postponed”. Nobody dies this year.','各村联名的呈子递到了知府手里。新税“暂缓征收”。这一年，没死一个人。'),c:'good',fx:{align:4,fame:2}},
   {w:1,t:T('They rise without you. You hear of it from a refugee, months later.','他们没等你就反了。几个月后，你是从一个逃难的人嘴里听说的。'),c:'muted',fx:{happy:-3}}]}]});
I({id:'so_rise2r',age:[19,80],w:6,once:1,need:'so_rebel',when:soAfter('so_rebel'),ctx:s=>{const c=scene();c.lv=PW(1.05,5)(s);return c},
 text:()=>T('Your army, hungry and brave, armed with hoes and a few stolen spears, stands before the walls of the county seat. The garrison is small, but it is behind stone.','你的队伍饿着肚子，却个个不怕死，拿着锄头和几杆抢来的长枪，列在县城墙下。守军不多，可他们躲在石墙后头。'),
 opts:[{l:T('Storm the walls at dawn','天亮攻城'),fight:FG((s,c)=>c.lv,'injury',T('Storming the county seat','攻打县城'),T('the garrison','守城官兵'),()=>T('the garrison','守城官兵')),
   win:[{w:2,t:T('You are first over the wall. By noon the granary is open and the tax registers are burning in the square.','你第一个翻上城头。到晌午，粮仓开了，税册在广场上烧成了一堆火。'),c:'gold',fx:{fame:5,align:2,unflag:'so_rebel',flag:'so_rebel2'}},
    {w:s=>s.t.heart*.15,t:T('The city falls. You stop your men from looting, which costs you some of them and wins you the town.','城破了。你拦着手下不许抢掠，为此走了一些人，却赢下了全城的人心。'),c:'good',fx:{fame:4,align:5,unflag:'so_rebel',flag:'so_rebel2'}}],
   lose:[{t:T('The assault breaks on the gate. Half your men scatter into the hills. The rest follow you, more grimly now.','攻到城门就垮了。一半人散进了山里，剩下的跟着你，脸色更沉了。'),c:'bad',fx:{hurt:[6,14],cause:T('the walls of the county seat','县城城下'),unflag:'so_rebel',flag:['so_rebel2','so_rbweak']}}]},
  {l:T('Cut the roads and starve them out','断了粮道，围而不攻'),out:[{w:s=>s.smarts/25,t:T('Forty days. Then the garrison opens the gate and walks out with their hands up. Not a drop of blood.','围了四十天，守军开了城门，举着手走了出来。一滴血都没流。'),c:'gold',fx:{fame:4,align:4,unflag:'so_rebel',flag:'so_rebel2'}},
   {w:1,t:T('A relief column breaks through on the thirtieth day. You pull back into the hills with what is left.','第三十天，援兵杀开了一条路。你带着剩下的人退进了山里。'),c:'bad',fx:{fame:1,unflag:'so_rebel',flag:['so_rebel2','so_rbweak']}}]},
  {l:T('Send them home before it is too late','趁还来得及，遣散回家'),out:[{w:s=>.5+s.fame/40,t:T('You share out the grain you have and send them home by night. The rising dies quietly. Your name stays on the notices.','你把手头的粮分了，趁夜把人遣散回家。这场起事悄悄地熄了。告示上，你的名字还在。'),c:'muted',fx:{align:2,unflag:'so_rebel'}},
   {w:1,t:T('Some go home. Some call you a traitor and go on without you, and are cut down within the month.','有的回了家。有的骂你叛徒，自己接着干，不到一个月就被剿灭了。'),c:'bad',fx:{fame:-3,happy:-6,unflag:'so_rebel'}}]}]});
I({id:'so_rise2l',age:[19,80],w:6,once:1,need:'so_loyal',when:soAfter('so_loyal'),ctx:s=>{const c=scene();c.lv=PW(1,3)(s);return c},
 text:()=>T('The rising came anyway. The magistrate gives you thirty militiamen, a red sash, and points at the hills. Among the rebels, you are told, are men from the village who once asked you to lead them.','民变还是来了。县太爷给了你三十个乡勇、一条红腰带，往山上一指。听说山里的反民当中，有当初求你领头的那个村子的人。'),
 opts:[{l:T('Lead the attack','带队进剿'),fight:FG((s,c)=>c.lv,'injury',T('Into the hills','进山剿匪'),T('the rebels','反民'),()=>T('the rebels','反民')),
   win:[{w:2,t:T('The rebels break. The magistrate makes you captain of militia and pays a hundred taels. In the villages, mothers use your name to frighten children.','反民溃散了。县太爷让你当了乡勇头领，赏银一百两。村里的娘们拿你的名字吓唬孩子。'),c:'muted',fx:{money:100,fame:3,align:-4,unflag:'so_loyal'}},
    {w:s=>s.t.heart*.15,t:T('You win, and let the ringleader slip away in the night. You report him dead. Nobody checks.','你打赢了，却在夜里放走了领头的人，回报说他已经死了。没人去查。'),c:'good',fx:{money:60,align:3,unflag:'so_loyal'}}],
   lose:[{t:T('The militia run at the first rock thrown. You are left holding the hill alone, briefly.','乡勇被头一块石头砸得掉头就跑。你一个人守着山头，没守多久。'),c:'bad',fx:{hurt:[6,14],cause:T('the rebels','反民'),unflag:'so_loyal'}}]},
  {l:T('Change sides','临阵倒戈'),out:[{w:s=>s.fame/30+power(s)/60,t:T('You ride into the rebel camp with thirty militiamen behind you. They cheer. Now the rising has someone who knows the yamen from inside.','你带着三十个乡勇骑进了义军大营。山上一片欢呼。这下义军里有了一个摸得清衙门底细的人。'),c:'gold',fx:{wanted:2,align:5,fame:3,unflag:'so_loyal',flag:'so_rebel2'}},
   {w:1,t:T('The rebels do not trust you and the yamen will not forgive you. Both sides hunt you through the winter.','义军不信你，官府也不饶你。整个冬天，两边都在搜你。'),c:'bad',fx:{wanted:1,happy:-5,unflag:'so_loyal'}}]},
  {l:T('Negotiate a surrender','去谈招降'),out:[{w:s=>s.smarts/25+s.fame/50,t:T('They come down from the hills on your word, and the magistrate, for once, keeps his. The tax is halved.','他们凭你一句话下了山。县太爷这一回总算说话算数，粮税减了一半。'),c:'gold',fx:{align:6,fame:4,unflag:'so_loyal',deed:T('Talked a rising down from the hills without a battle','只身入山，劝降义军，免了一场厮杀')}},
   {w:1,t:T('They come down on your word. The magistrate hangs the leaders anyway. You cannot look at the hills now.','他们凭你一句话下了山。县太爷照样把领头的吊死了。从此你不敢再望那片山。'),c:'bad',fx:{align:-2,happy:-8,unflag:'so_loyal'}}]}]});
I({id:'so_rise3r',age:[20,85],w:6,once:1,need:'so_rebel2',when:soAfter('so_rebel2'),ctx:s=>{const c=scene();c.lv=PW(s.flags.so_rbweak!=null?1.15:.95,6)(s);return c},
 text:()=>T('An envoy from the court rides up under a white flag. He offers amnesty, and an officer’s commission for you, if you hand over your lieutenants. Ten thousand imperial troops are three days behind him.','朝廷的使者打着白旗来了。他说，只要你交出手下几个头目，就赦你无罪，还封你个武官。他身后三天路程，是一万官军。'),
 opts:[{l:T('Accept the amnesty','接受招安'),out:[{w:s=>.5+s.smarts/30,t:T('The envoy keeps his word. You get a commission, your lieutenants get pardons, and the tax is quietly lowered.','使者说话算话。你得了官职，几个头目也都赦了，粮税悄悄降了下来。'),c:'gold',fx:{money:200,fame:3,align:1,unflag:['so_rebel2','so_rbweak'],deed:T('Led a peasant rising and won it an amnesty','领义军起事，终获招安')}},
   {w:1,t:T('Your lieutenants are beheaded the day after you sign. You have a title and no friends.','你画押的第二天，几个头目就被砍了头。你有了官衔，却没了朋友。'),c:'bad',fx:{money:200,align:-10,happy:-10,unflag:['so_rebel2','so_rbweak'],deed:T('Sold out a peasant rising for an officer’s commission','以义军头目的人头换了一顶官帽')}}]},
  {l:T('Fight the imperial army','跟官军决一死战'),fight:FG((s,c)=>c.lv,'death',T('The last battle of the rising','义军决战'),T('the imperial army','官军'),()=>T('the imperial army','官军')),
   win:[{w:s=>s.align>20?2:1,t:T('The imperial army breaks in the river mud. The prefect flees, the court negotiates, and the new tax is struck from the books. You go home and plant rice.','官军在河滩烂泥里溃了。知府跑了，朝廷只得议和，新税从册子上一笔勾销。你回家种稻子去了。'),c:'gold',fx:{fame:10,align:8,unflag:['so_rebel2','so_rbweak'],deed:T('Led a peasant army that broke an imperial army','率义军大破官军')}},
    {w:1,t:T('You win, and the province is yours. Within five years you live in the prefect’s mansion, and people say you have become what you fought.','你赢了，一省之地都归了你。不出五年，你住进了知府的宅子，人们说你成了你当初要打倒的那种人。'),c:'gold',fx:{fame:10,money:400,align:-5,unflag:['so_rebel2','so_rbweak'],deed:T('Rose against the court and ruled a province','举兵抗命，割据一方')}}],
   lose:[{t:T('The rising is crushed. You escape through the reeds with a price on your head and the dead behind you.','义军被剿灭了。你从芦苇荡里逃了出去，头上悬着赏格，身后是一地死人。'),c:'bad',fx:{wanted:3,hurt:[10,20],cause:T('the imperial army','官军'),unflag:['so_rebel2','so_rbweak'],deed:T('Led a peasant rising that was crushed','领义军起事，兵败')}}]},
  {l:T('Dissolve the army and vanish','解散队伍，隐姓埋名'),out:[{w:s=>s.t.luck*.2+s.smarts/50,t:T('You burn the banners and walk away in a farmer’s hat. The troops find an empty camp and a lot of hoes.','你烧了旗子，戴着斗笠走了。官军进营时，只看到一地锄头。'),c:'muted',fx:{wanted:1,fame:-2,unflag:['so_rebel2','so_rbweak']}},
   {w:1,t:T('A handful of your men refuse to leave you. For the rest of your life, there are always a few of them nearby.','有几个弟兄说什么也不肯走。此后一辈子，你身边总有那么几个人。'),c:'muted',fx:{wanted:1,meet:'sworn',bond:80,unflag:['so_rebel2','so_rbweak']}}]}]});

/* =========================== BIG: the border war =========================== */
I({id:'so_war1',age:[16,60],cd:25,w:s=>['north','west','capital'].includes(s.region)?1.3:.5,ctx:s=>{const c=scene();c.npc=npc(s,{occ:27,sex:'f',age:rint(25,40)});return c},
 text:()=>T('Steppe horsemen have broken through at a frontier pass. The roads are full of refugees with carts and grandmothers. The army calls for volunteers: ten taels and a pardon for any crime.','草原上的骑兵从一处边关隘口杀了进来。路上挤满了逃难的人，推着车，背着老人。军中在招募义勇：十两银子，过往罪行一笔勾销。'),
 opts:[{l:T('Enlist','投军'),out:[{w:s=>.5+power(s)/50,t:T('The recruiting officer watches you lift a cart and makes you a squad leader on the spot.','募兵的军官看你单手抬起一辆车，当场让你做了伍长。'),c:'good',fx:{money:10,fame:1,flag:'so_army',f:s=>{s.wanted=0}}},
   {w:1,t:T('You are given a spear, a number, and the job of digging latrines. Still, you are in.','你领了一杆枪、一个编号，还有挖茅坑的差事。好歹是入伍了。'),c:'muted',fx:{money:10,flag:'so_army',f:s=>{s.wanted=0}}}]},
  {l:T('Help the refugees','帮难民'),out:[{w:s=>s.t.heart*.2,t:c=>T(`A young widow, ${c.npc.en}, is trying to keep twelve orphans together on the road. You take the other end of the line.`,`一个年轻寡妇${c.npc.zh}，正拼命拢着路上的十二个孤儿。你接过了队伍的另一头。`),c:'muted',next:'so_war2',keep:1},
   {w:1,t:T('You follow the refugees to a temple where two thousand people share one well.','你跟着难民到了一座庙里，两千人共用一口井。'),c:'muted',next:'so_war2',keep:1}]},
  {l:T('Sell supplies to the army','向军中卖粮草'),if:s=>s.money>=80,out:[{w:s=>s.smarts/30,t:T('Salted pork and horse fodder at war prices. You do very well.','咸肉和马料都按战时的价钱卖，你赚得盆满钵满。'),c:'muted',fx:{money:[100,250],align:-2}},
   {w:1,t:T('The quartermaster pays in army IOUs. They are worth exactly what the paper is worth.','军需官给你打了白条。那白条值多少钱，就看那张纸值多少钱。'),c:'bad',fx:{money:-60,happy:-3}}]}]});
I({id:'so_war2',only:1,noThread:1,
 text:()=>T('The refugee camp is a temple yard of mud. The local gentry want the refugees gone before they steal the seed grain, and have hired men with clubs to see to it.','难民营是一片泥泞的庙院。本地的乡绅怕难民偷了种粮，想把人赶走，已经雇了一帮拿棍子的打手。'),
 opts:[{l:T('Organise the camp','把营地管起来'),out:[{w:s=>s.smarts/30+s.fame/40,t:T('Latrines downhill, the well guarded, rations by family. The camp stops dying. People start calling you “elder”.','茅坑挖在下坡，水井有人守，口粮按户分。营里不再死人了。大家开始叫你“当家的”。'),c:'good',fx:{align:6,fame:3}},
   {w:1,t:T('Dysentery runs through the camp anyway, and through you.','痢疾照样在营里传开了，也传到了你身上。'),c:'bad',fx:{align:4,ill:'fever'}}]},
  {l:T('Stand between them and the clubs','挡在打手前面'),fight:FG(PW(.9,2),'injury',T('Clubs at the temple gate','庙门前的棍棒'),T('the gentry’s thugs','乡绅的打手'),()=>T('the gentry’s thugs','乡绅的打手')),
   win:[{t:T('The thugs go home with sore heads. The gentry decide charity is cheaper, and send rice.','打手们抱着脑袋回去了。乡绅们算了算，觉得施舍更划算，送来了米。'),c:'good',fx:{align:5,fame:3}},
    {w:s=>s.fame/40,t:T('Word of the fight reaches the army. An officer comes to see who is defending the temple, and offers the camp a guard.','这一仗传到了军中。一位军官过来看是谁在护庙，还派了兵来守营。'),c:'good',fx:{align:5,fame:4}}],
   lose:[{t:T('They clear the temple. The refugees scatter along the road, and you limp after them.','他们把庙清空了。难民们沿路四散，你一瘸一拐地跟在后头。'),c:'bad',fx:{hurt:[5,12],cause:T('the gentry’s thugs','乡绅的打手'),align:3}}]},
  {l:T('Find them land in the hills','在山里给他们找块地'),out:[{w:s=>s.t.luck*.2+s.smarts/50,t:T('An abandoned valley with a good spring. They build a village there and name the well after you.','一处荒了的山谷，有一眼好泉。他们在那里建了个村子，水井用你的名字命名。'),c:'gold',fx:{fame:4,align:6,deed:T('Led refugees of the border war to a valley of their own','带边关难民找到了安身的山谷')}},
   {w:1,t:T('The hill people object with arrows. You lead the refugees back down, fewer than went up.','山里的人用箭表示了反对。你带着难民下了山，人比上山时少了。'),c:'bad',fx:{align:3,happy:-4}}]}]});
I({id:'so_war3',age:[17,70],w:6,once:1,need:'so_army',when:soAfter('so_army'),ctx:s=>{const c=scene();c.lv=PW(1.05,6)(s);return c},
 text:()=>T('Wolf-Tooth Pass. The horsemen come at dawn, three thousand of them, and your company holds the narrowest part of the road.','狼牙口。天刚亮，三千骑兵压了过来。你所在的营守着山道最窄的那一段。'),
 opts:[{l:T('Hold the line','死守阵地'),fight:FG((s,c)=>c.lv,'injury',T('Wolf-Tooth Pass','狼牙口之战'),T('the steppe horsemen','草原骑兵'),()=>T('the steppe horsemen','草原骑兵')),
   win:[{w:2,t:T('The pass holds. Your name is in the general’s dispatch, spelled correctly.','隘口守住了。你的名字上了将军的捷报，一个字都没写错。'),c:'gold',fx:{fame:6,align:2,money:80,unflag:'so_army',flag:'so_army2'}},
    {w:s=>power(s)/80,t:T('You unhorse their captain yourself. The army will be telling it for years, a little bigger each time.','你亲手把敌军的头领挑下了马。这事军中会讲上好几年，一回比一回讲得大。'),c:'gold',fx:{fame:8,skill:2,unflag:'so_army',flag:'so_army2'}}],
   lose:[{t:T('An arrow, a fall, and then a cart full of wounded men. The pass holds without you.','一支箭，一个跟头，然后就躺在了一车伤兵当中。隘口守住了，跟你没什么关系。'),c:'bad',fx:{hurt:[8,18],cause:T('Wolf-Tooth Pass','狼牙口之战'),unflag:'so_army',flag:'so_army2',f:s=>addCond(s,'fracture',1)}}]},
  {l:T('Lead a night raid on their horses','夜袭敌军马群'),out:[{w:s=>s.smarts/30+power(s)/80,t:T('You cut the picket lines and set the dry grass alight. Three thousand horses stampede back to the steppe without their riders.','你们砍断拴马的绳子，点着了枯草。三千匹马没了骑手，一窝蜂地逃回了草原。'),c:'gold',fx:{fame:8,unflag:'so_army',flag:'so_army2',deed:T('Led the night raid at Wolf-Tooth Pass','狼牙口夜袭马群')}},
   {w:1,t:T('A sentry sees you. You crawl back through the frost, two men fewer.','被哨兵发现了。你们在霜地里爬了回来，少了两个弟兄。'),c:'bad',fx:{hurt:[6,14],cause:T('a failed night raid','夜袭失手'),unflag:'so_army',flag:'so_army2',f:s=>addCond(s,'wound',1)}}]},
  {l:T('Desert in the night','连夜开小差'),out:[{w:s=>s.t.luck*.2,t:T('You are over the hill before the horns blow. Nobody comes after one more deserter.','号角还没吹，你已经翻过了山。多一个逃兵，没人来追。'),c:'muted',fx:{wanted:1,align:-4,unflag:'so_army'}},
   {w:1,t:T('Caught at the river, flogged, and put back in the line, in the front this time.','在河边被逮住，打了一顿鞭子，又塞回了阵里——这回是第一排。'),c:'bad',fx:{hurt:[5,10],cause:T('a flogging for desertion','逃兵的鞭刑'),unflag:'so_army',flag:'so_army2'}}]}]});
I({id:'so_war4',age:[18,75],w:6,once:1,need:'so_army2',when:soAfter('so_army2'),
 text:()=>T('The war ends. The general is recalled to the capital, where the eunuchs say he plotted treason. The army’s back pay has vanished somewhere between the treasury and the paymaster. Your comrades are sharpening their spears.','仗打完了。将军被召回京城，宫里的太监说他图谋不轨。三军的欠饷，在户部和粮台之间不知去向。你的弟兄们正在磨枪。'),
 opts:[{l:T('March on the paymaster with them','跟弟兄们去找粮台讨饷'),out:[{w:s=>power(s)/60+s.fame/40,t:T('The paymaster finds the silver in his own cellar, remarkably quickly. Everyone is paid, and you a little extra.','粮台官从自家地窖里找出了银子，找得飞快。人人领到了饷，你还多拿了一份。'),c:'good',fx:{money:150,fame:3,align:2,wanted:1,unflag:'so_army2'}},
   {w:1,t:T('The court calls it mutiny. You get your pay in the end, and your name on a list.','朝廷说这是兵变。饷最后是拿到了，你的名字也上了一份名单。'),c:'bad',fx:{money:60,wanted:2,unflag:'so_army2'}}]},
  {l:T('Go to the capital and speak for the general','进京替将军作证'),out:[{w:s=>s.fame/30+s.smarts/40,t:T('Your account of the pass, given before the Ministry of War, helps clear him. He does not forget the soldier who came.','你在兵部大堂上讲了狼牙口的经过，帮他洗清了罪名。他忘不了那个肯来作证的兵。'),c:'gold',fx:{money:100,fame:4,align:4,unflag:'so_army2',deed:T('Spoke for a wronged general before the Ministry of War','在兵部为蒙冤的将军作证')}},
   {w:1,t:T('He is executed anyway. You are lucky to get out of the capital with your head.','他还是被斩了。你能带着脑袋出京城，已经算命大。'),c:'bad',fx:{align:3,happy:-6,unflag:'so_army2'}}]},
  {l:T('Take your discharge papers and go home','领了退伍文书回家'),out:[{w:2,t:T('Thirty taels, a scar or two, and a lot of stories nobody at home wants to hear.','三十两银子，一两道疤，还有一肚子家里人不爱听的故事。'),c:'muted',fx:{money:30,happy:3,unflag:'so_army2'}},
   {w:s=>s.t.luck*.1,t:T('In the confusion of the discharge you are handed an officer’s horse by mistake. Nobody asks for it back.','退伍的时候乱成一团，有人错把一匹军官的马牵给了你。也没人来要。'),c:'good',fx:{item:'horse',happy:4,unflag:'so_army2'}}]}]});

/* =========================== BIG: the city under siege (one long year) =========================== */
I({id:'so_siege1',age:[16,75],cd:30,w:s=>soWd(s).u>=2?1.6:.5,tags:['town'],
 text:()=>T('A warlord’s army closes round the walled city where you are staying. The gates are shut. The prefect calls every able body to the walls.','一个军阀的人马围住了你暂住的这座城。城门关了。知府下令，能动的都上城墙。'),
 opts:[{l:T('Go up on the walls','上城墙'),out:[{w:s=>power(s)/50,t:T('The garrison commander sees you handle a spear and gives you a gate tower.','守将见你使枪有模有样，把一座城门楼交给了你。'),c:'good',fx:{fame:2},next:'so_siege2',keep:1},
   {w:1,t:T('You are given a spear and a stretch of wall between a baker and a monk.','你领了一杆枪，被分到一段城墙上，左边是个烧饼铺的，右边是个和尚。'),c:'muted',next:'so_siege2',keep:1}]},
  {l:T('Buy up food while you can','趁早囤粮'),if:s=>s.money>=40,out:[{w:s=>s.smarts/30,t:T('By the second month you are selling rice by the ounce. You leave the city rich, and nobody there will ever speak to you.','到第二个月，你已经按两卖米了。你离城时发了财，城里却再没人肯跟你说话。'),c:'muted',fx:{money:[80,200],align:-6,fame:-2}},
   {w:1,t:T('The prefect requisitions every private store on the third day. Yours goes to the soldiers, with a receipt.','第三天知府就征了全城的存粮。你囤的米全进了兵营，换回一张收条。'),c:'bad',fx:{money:-40,align:1}}]},
  {l:T('Slip out before the ring closes','趁合围前溜出去'),out:[{w:s=>s.t.luck*.2+s.smarts/50,t:T('Out through a drain at midnight. You watch the city’s fires from a hilltop for two months.','半夜钻阴沟出了城。之后两个月，你在山头上看着城里的火光。'),c:'muted',fx:{align:-1}},
   {w:1,t:T('Arrows from the dark. You scramble back over the wall with one in your shoulder.','黑暗里飞来一阵箭。你肩上插着一支，连滚带爬地翻回了城里。'),c:'bad',fx:{hurt:[5,12],cause:T('an arrow in the dark','黑暗中的冷箭')},next:'so_siege2',keep:1}]}]});
I({id:'so_siege2',only:1,noThread:1,
 text:()=>T('Day thirty. The horses have been eaten. A deserter from the other side says they are digging a tunnel toward the east wall, and that someone inside has been paid to open a gate.','第三十天。马都吃光了。一个从城外逃进来的兵说，敌军正朝东墙挖地道，城里还有人收了钱，要开城门。'),
 opts:[{l:T('Dig a counter-tunnel and wait in the dark','挖条对头地道，在黑暗里等'),fight:FG(PW(1,4),'injury',T('Fighting underground','地道里的厮杀'),T('the sappers','挖地道的敌兵'),()=>T('the sappers','挖地道的敌兵')),
   win:[{w:2,t:T('You meet them in the dark with knives and smoke. The tunnel is collapsed with them in it.','你们在黑暗里用刀和烟迎上了他们。地道塌了，人都埋在了里头。'),c:'good',fx:{fame:3,f:(s,c)=>{c.won=1}},next:'so_siege3',keep:1},
    {w:s=>s.smarts/40,t:T('You fill their tunnel with chili smoke from the city’s spice shops. They come out coughing into the arms of the garrison.','你把城里香料铺的辣椒都拿来熏地道。敌兵咳着爬出来，正撞进守军怀里。'),c:'good',fx:{fame:3,smarts:1,f:(s,c)=>{c.won=1}},next:'so_siege3',keep:1}],
   lose:[{t:T('The tunnel fight goes badly. You are dragged out by the ankles, and the east wall is shaken.','地道里没打好。你被人拽着脚踝拖了出来，东墙也被掏松了。'),c:'bad',fx:{hurt:[6,14],cause:T('a tunnel fight','地道恶战')},next:'so_siege3',keep:1}]},
  {l:T('Hunt for the traitor','揪出内奸'),out:[{w:s=>s.smarts/25+s.t.wit*.1,t:T('The granary master has new silver and old grudges. He is caught with the gate key in his boot.','管粮仓的有了来路不明的新银子，又有旧怨。他靴子里藏着城门钥匙，被当场拿住。'),c:'good',fx:{align:3,fame:2},next:'so_siege3',keep:1},
   {w:1,t:T('You name the wrong man. A frightened mob hangs a cobbler. The real traitor is never found.','你指错了人。惊慌的人群吊死了一个鞋匠。真正的内奸始终没找到。'),c:'bad',fx:{align:-3,happy:-5},next:'so_siege3',keep:1}]},
  {l:T('Break out to fetch a relief army','突围去搬救兵'),out:[{w:s=>power(s)/50+s.t.luck*.1,t:T('Over the wall on a rope at the dark of the moon, through the lines, and four days’ hard riding. You come back with an army.','月黑之夜顺着绳子下了城，穿过敌营，拼命骑了四天。你带着援军回来了。'),c:'gold',fx:{fame:4,f:(s,c)=>{c.relief=1}},next:'so_siege3',keep:1},
   {w:1,t:T('Cut off and wounded, you hide in the reeds for three days. The siege ends without you.','被截住了，还受了伤，你在芦苇里藏了三天。围城的事，最后跟你没了关系。'),c:'bad',fx:{hurt:[6,14],cause:T('breaking the siege lines','突围'),f:s=>addCond(s,'wound',1)}}]}]});
I({id:'so_siege3',only:1,noThread:1,
 text:c=>c.relief?T('Day sixty-one. The relief army’s banners appear on the ridge. The warlord’s men are caught between the walls and the hills. The prefect wants one last push from inside.','第六十一天。援军的旗号出现在山梁上。军阀的人马被夹在城墙和山岭之间。知府要城里再冲一回。')
  :T('Day sixty-one. No relief has come. The warlord sends a messenger: surrender the city and only the prefect dies, or be taken and everyone dies.','第六十一天。援军还是没来。军阀派人传话：献城，只杀知府一人；不献，破城之后鸡犬不留。'),
 opts:[{l:T('Lead the final sally','带头冲出城去'),fight:FG(PW(1.05,5),'injury',T('The last sally','最后一冲'),T('the besiegers','围城的敌军'),()=>T('the besiegers','围城的敌军')),
   win:[{w:2,t:T('The gate opens and you are first through it. The siege lines break like old rope. The city rings every bell it has.','城门一开，你第一个冲了出去。敌军的营垒像烂绳子一样断了。全城的钟都敲响了。'),c:'gold',fx:{fame:8,align:4,deed:T('Led the sally that broke a sixty-day siege','率众突围，解了六十日之围')}},
    {w:s=>s.t.luck*.1+s.fame/60,t:T('In the confusion you capture the warlord himself, hiding in a cart of turnips. The prefect gives you his sword.','乱军中你在一车萝卜里活捉了军阀本人。知府把他的佩剑送给了你。'),c:'gold',fx:{fame:10,money:120,item:'steelsword',deed:T('Captured a warlord in a cart of turnips','在萝卜车里活捉了军阀')}}],
   lose:[{t:T('You go down in the gateway. The city holds anyway, and you wake in the temple they have turned into a hospital.','你在城门洞里倒下了。城还是守住了，你醒来时躺在改成伤兵营的庙里。'),c:'bad',fx:{hurt:[10,20],cause:T('the last sally','最后一冲'),align:3,f:s=>addCond(s,'fracture',1)}}]},
  {l:T('Negotiate terms for the townsfolk','替城里百姓去谈条件'),out:[{w:s=>s.smarts/25+s.fame/30,t:T('You walk out alone under a white cloth. You come back with a written promise: no looting, no burning. It is kept.','你一个人举着白布走出城去，带回一纸文书：不抢，不烧。对方守了约。'),c:'gold',fx:{align:6,fame:5,deed:T('Walked out alone to bargain for a besieged city','孤身出城，为一城百姓议和')}},
   {w:1,t:T('They promise everything and loot anyway. You save the families in your own street, and that is all.','他们满口答应，进城照样抢。你只护住了自己那条街上的几户人家。'),c:'bad',fx:{align:2,happy:-8}}]},
  {l:T('Hide the children in the temple vaults','把孩子们藏进庙里的地窖'),out:[{w:s=>s.t.luck*.15+s.smarts/50,t:T('Forty children in the dark, and you at the door. Whatever happens above, nobody finds them.','四十个孩子藏在黑暗里，你守在门口。不管上面发生了什么，谁也没找到他们。'),c:'good',fx:{align:7,fame:2}},
   {w:1,t:T('A soldier hears a baby. You talk, then fight, then talk again. In the end he takes your silver and goes away.','一个兵听见了婴儿的哭声。你先是说，后来打，最后又说。他拿走你的银子，走了。'),c:'muted',fx:{align:5,f:s=>pay(s,-Math.min(s.money,rint(20,80))),hurt:[3,8],cause:T('a looting soldier','抢掠的兵')}}]}]});

/* =========================== BIG: the dead man’s ledger and the Inner Watch =========================== */
I({id:'so_ledger1',age:[18,70],once:1,w:.9,tags:['wander'],ctx:s=>{const c=scene();c.npc=npc(s,{occ:1,sex:'m',age:rint(30,45)});c.lv=PW(1,4)(s);return c},
 text:c=>T(`At a roadside inn, a man in a scholar’s gown, ${c.npc.en}, staggers in with an arrow in his side. He presses an oilcloth packet into your hands. “The Inner Watch… the Director’s accounts… the Censorate…” He dies. Hooves in the yard: men in black coats.`,`路边客栈里，一个穿儒衫的人跌跌撞撞地闯进来，肋下插着一支箭，是${c.npc.zh}。他把一个油布包塞到你手里。“内缉司……督公的账……都察院……”话没说完就断了气。院子里传来马蹄声：一群穿黑袍的人。`),
 opts:[{l:T('Hide the packet and play dumb','藏好包裹，装糊涂'),out:[{w:s=>s.smarts/30+s.t.luck*.1,t:T('“Drunk scholar,” you say. “Fell off his horse.” They look at you a long time, and leave.','“喝醉的书生，”你说，“从马上摔下来的。”他们盯着你看了好半天，走了。'),c:'muted',fx:{flag:'so_ledger'}},
   {w:1,t:T('They search you roughly, miss the packet in your boot, and take a long look at your face.','他们粗暴地搜了你的身，没搜到靴筒里的包裹，却把你的脸看了很久。'),c:'muted',fx:{flag:'so_ledger',wanted:1}}]},
  {l:T('Fight the men in black','跟黑袍人动手'),fight:FG((s,c)=>c.lv,'injury',T('Men in black at the inn','客栈里的黑袍人'),T('agents of the Inner Watch','内缉司的番子'),()=>T('the Inner Watch agents','内缉司番子')),
   win:[{t:T('They leave two of their number on the floor. Now they know you have it.','他们在地上留下了两个同伙。这下他们知道东西在你手里了。'),c:'muted',fx:{flag:'so_ledger',fame:1,wanted:1}}],
   lose:[{t:T('They take the packet from your hand and leave you bleeding beside its owner.','他们从你手里夺走了包裹，把你扔在死者身边，血流了一地。'),c:'bad',fx:{hurt:[8,16],cause:T('agents of the Inner Watch','内缉司的番子'),f:s=>addCond(s,'inner',1)}}]},
  {l:T('Hand it over','交出去'),out:[{w:2,t:T('They pay you fifty taels “for your loyalty to the throne”. You do not look at the dead man.','他们赏了你五十两，“嘉奖忠心”。你没去看那个死人。'),c:'muted',fx:{money:50,align:-6}},
   {w:s=>(11-s.t.luck)*.1,t:T('They decide a witness is a loose end. You barely get out of the window.','他们觉得活口终究是个麻烦。你差一点没能从窗户逃出去。'),c:'bad',fx:{align:-4,hurt:[6,12],cause:T('agents of the Inner Watch','内缉司的番子')}}]}]});
I({id:'so_ledger2',age:[19,80],w:6,once:1,need:'so_ledger',when:soAfter('so_ledger'),ctx:s=>{const c=scene();c.lv=PW(1.05,5)(s);return c},
 text:()=>T('You read the ledger at last: bribes, murders, and the Director of the Inner Watch’s name on every page. For a month now, someone has been following you. Tonight they come.','你终于读完了那本账：贿赂、人命，每一页上都有内缉司督公的名字。这一个月，总有人跟着你。今夜，他们来了。'),
 opts:[{l:T('Stand and fight','迎战'),fight:FG((s,c)=>c.lv,'injury',T('The Inner Watch comes at night','内缉司夜袭'),T('agents of the Inner Watch','内缉司的番子'),()=>T('the Inner Watch agents','内缉司番子')),
   win:[{w:2,t:T('Four of them, and you are still standing. The ledger is safe. They will send more.','来了四个，你还站着。账册保住了。他们还会再派人来。'),c:'good',fx:{fame:2,unflag:'so_ledger',flag:'so_ledger2'}},
    {w:s=>s.smarts/40,t:T('One of them, wounded, tells you which censor the Director fears most. Then he runs.','其中一个受了伤，告诉你督公最怕哪位御史，然后跑了。'),c:'good',fx:{smarts:1,unflag:'so_ledger',flag:'so_ledger2'}}],
   lose:[{t:T('They take the ledger and leave you for dead. You are not, quite.','他们拿走了账册，以为你死了。你还没死，差一点。'),c:'bad',fx:{hurt:[10,18],cause:T('agents of the Inner Watch','内缉司的番子'),unflag:'so_ledger',f:s=>addCond(s,'inner',1)}}]},
  {l:T('Go to ground','躲起来'),out:[{w:s=>s.smarts/30+s.t.luck*.15,t:T('A fishing family on a reed island hides you through the winter. In spring the watchers have moved on.','芦苇荡里一户打鱼的人家把你藏了一冬。开春时，盯梢的人走了。'),c:'good',fx:{unflag:'so_ledger',flag:'so_ledger2'}},
   {w:1,t:T('The monks who take you in are paid informers. You flee at night with the ledger and nothing else.','收留你的和尚是拿了钱的眼线。你半夜跑了，除了账册什么都没带。'),c:'bad',fx:{f:s=>pay(s,-Math.min(s.money,rint(30,100))),happy:-3,unflag:'so_ledger',flag:'so_ledger2'}}]},
  {l:T('Copy it and send copies to famous names','抄几份，寄给有名望的人'),out:[{w:s=>s.fame/25+s.smarts/40,t:T('Three copies go to three sect masters. Now killing you would not bury it, and the men in black stop coming.','三份抄本寄给了三位掌门。如今杀了你也捂不住了，黑袍人不再来了。'),c:'good',fx:{fame:3,unflag:'so_ledger',flag:'so_ledger2'}},
   {w:1,t:T('One copy is intercepted. Now they know exactly what you have.','有一份被截住了。这下他们完全清楚你手里有什么了。'),c:'bad',fx:{wanted:1,unflag:'so_ledger',flag:'so_ledger2'}}]}]});
I({id:'so_ledger3',age:[20,85],w:6,once:1,need:'so_ledger2',when:soAfter('so_ledger2'),
 text:()=>T('The capital. The old Censor is said to be the one honest man at court. The same evening, the Director’s nephew invites you to dinner, and slides a box with a thousand taels across the table.','京城。都说那位老御史是朝中唯一的清官。当天晚上，督公的侄子请你吃饭，把一只装着一千两银子的匣子推到了你面前。'),
 opts:[{l:T('Deliver it to the Censor','送到御史手里'),out:[{w:s=>(s.align>30?2:1)+s.fame/50,t:T('The Director falls within a season. Heads roll in the capital. You are given three hundred taels quietly, and asked even more quietly to leave.','一季之内，督公倒了台，京城里人头滚滚。有人悄悄塞给你三百两，又更悄悄地请你离京。'),c:'gold',fx:{money:300,fame:6,align:8,unflag:'so_ledger2',deed:T('Carried the ledger that brought down the Director of the Inner Watch','送出扳倒内缉司督公的账册')}},
   {w:1,t:T('The Censor reads it, weeps, and burns it. “Not yet. Not while the Emperor is this young.” You walk out into a city that has not changed.','老御史读完，落了泪，然后把它烧了。“还不是时候。皇上还太小。”你走出门，京城还是那个京城。'),c:'muted',fx:{align:3,happy:-6,unflag:'so_ledger2'}}]},
  {l:T('Take the thousand taels','收下一千两'),out:[{w:2,t:T('You live comfortably for years. You never read the news from the capital again.','此后多年你过得很舒坦，再也不看京里的消息。'),c:'muted',fx:{money:1000,align:-15,unflag:'so_ledger2'}},
   {w:s=>(11-s.t.luck)*.1,t:T('They pay you, and then send someone to make sure you stay bought. The wine at a wayside inn tastes of almonds.','他们给了钱，又派人来确保你永远闭嘴。路边小店的酒，有股杏仁味。'),c:'bad',fx:{money:1000,align:-15,hurt:[8,16],cause:T('poisoned wine','毒酒'),unflag:'so_ledger2',f:s=>addCond(s,'poison',1)}}]},
  {l:T('Paste copies on the palace gate','把抄本贴满宫门'),out:[{w:s=>s.fame/30+s.t.luck*.1,t:T('By noon the whole capital has read it. Even the Director cannot bury a thing every tea seller can recite. He is sent to guard a tomb.','不到晌午，全京城都读到了。连卖茶的都能背上几句，督公再也捂不住，被打发去守皇陵了。'),c:'gold',fx:{fame:10,align:8,wanted:2,unflag:'so_ledger2',deed:T('Posted the Inner Watch’s crimes on the palace gate','把内缉司的罪证贴上了宫门')}},
   {w:1,t:T('The Watch has the copies down before dawn, and you in a cell before noon.','天没亮，内缉司就把抄本撕光了；不到晌午，你就进了大牢。'),c:'bad',fx:{jail:1,align:6,unflag:'so_ledger2',deed:T('Was jailed for posting the Inner Watch’s crimes on the palace gate','因张贴内缉司罪证而下狱')}}]}]});
